enum {
    PTN_ENT_SINGLE_QUOTE = 1,
    PTN_ENT_DOC_TYPE_MASK = PTN_ENT_HTML5,
    PTN_HTML_DEFAULT_FLAGS = PTN_ENT_QUOTES | PTN_ENT_SUBSTITUTE | PTN_ENT_HTML401,
};

static int ptn_ucwords_is_delimiter(unsigned char byte, PtnStringOperand delimiters) {
    for (size_t i = 0; i < delimiters.len; i++) {
        if ((unsigned char)delimiters.data[i] == byte) {
            return 1;
        }
    }
    return 0;
}

static PtnValue ptn_internal_ucwords(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "ucwords", 1, "string", args[0], line);
    PtnStringOperand delimiters = argc >= 2
        ? ptn_internal_expect_string_arg(runtime, "ucwords", 2, "separators", args[1], line)
        : ptn_string_operand_borrowed(" \t\r\n\f\v");

    char *mapped = malloc(string.len + 1);
    if (mapped == NULL) {
        ptn_abort_out_of_memory();
    }

    int uppercase_next = 1;
    for (size_t i = 0; i < string.len; i++) {
        unsigned char byte = (unsigned char)string.data[i];
        if (uppercase_next && byte >= 'a' && byte <= 'z') {
            mapped[i] = (char)('A' + (byte - 'a'));
        } else {
            mapped[i] = (char)byte;
        }
        uppercase_next = ptn_ucwords_is_delimiter(byte, delimiters);
    }
    mapped[string.len] = '\0';

    size_t len = string.len;
    ptn_string_operand_free(string);
    ptn_string_operand_free(delimiters);
    return ptn_owned_string_len(mapped, len);
}

static int ptn_html_match_literal(
    const char *data,
    size_t len,
    size_t offset,
    const char *literal,
    size_t *matched_len
) {
    size_t literal_len = strlen(literal);
    if (literal_len <= len - offset && memcmp(data + offset, literal, literal_len) == 0) {
        *matched_len = literal_len;
        return 1;
    }
    return 0;
}

static int ptn_html_numeric_entity_value(
    const char *data,
    size_t len,
    size_t offset,
    size_t *matched_len,
    unsigned int *value
) {
    if (offset + 3 > len || data[offset] != '&' || data[offset + 1] != '#') {
        return 0;
    }

    size_t cursor = offset + 2;
    int base = 10;
    if (cursor < len && (data[cursor] == 'x' || data[cursor] == 'X')) {
        base = 16;
        cursor++;
    }
    if (cursor >= len) {
        return 0;
    }

    unsigned int parsed = 0;
    size_t digits = 0;
    while (cursor < len) {
        unsigned char byte = (unsigned char)data[cursor];
        unsigned int digit;
        if (byte >= '0' && byte <= '9') {
            digit = (unsigned int)(byte - '0');
        } else if (base == 16 && byte >= 'a' && byte <= 'f') {
            digit = 10 + (unsigned int)(byte - 'a');
        } else if (base == 16 && byte >= 'A' && byte <= 'F') {
            digit = 10 + (unsigned int)(byte - 'A');
        } else {
            break;
        }
        if (digit >= (unsigned int)base) {
            break;
        }
        if (parsed > (UINT_MAX - digit) / (unsigned int)base) {
            return 0;
        }
        parsed = parsed * (unsigned int)base + digit;
        digits++;
        cursor++;
    }
    if (digits == 0 || cursor >= len || data[cursor] != ';') {
        return 0;
    }

    *matched_len = cursor - offset + 1;
    *value = parsed;
    return 1;
}

static int ptn_html_entity_decode_char(
    const char *data,
    size_t len,
    size_t offset,
    int64_t flags,
    char *decoded,
    size_t *matched_len
) {
    if (ptn_html_match_literal(data, len, offset, "&amp;", matched_len)) {
        *decoded = '&';
        return 1;
    }
    if (ptn_html_match_literal(data, len, offset, "&lt;", matched_len)) {
        *decoded = '<';
        return 1;
    }
    if (ptn_html_match_literal(data, len, offset, "&gt;", matched_len)) {
        *decoded = '>';
        return 1;
    }
    if ((flags & PTN_ENT_COMPAT) != 0 &&
        ptn_html_match_literal(data, len, offset, "&quot;", matched_len)) {
        *decoded = '"';
        return 1;
    }
    if ((flags & PTN_ENT_SINGLE_QUOTE) != 0 &&
        (flags & PTN_ENT_DOC_TYPE_MASK) != PTN_ENT_HTML401 &&
        ptn_html_match_literal(data, len, offset, "&apos;", matched_len)) {
        *decoded = '\'';
        return 1;
    }

    unsigned int value = 0;
    if (!ptn_html_numeric_entity_value(data, len, offset, matched_len, &value)) {
        return 0;
    }
    if (value == 38) {
        *decoded = '&';
        return 1;
    }
    if (value == 60) {
        *decoded = '<';
        return 1;
    }
    if (value == 62) {
        *decoded = '>';
        return 1;
    }
    if (value == 34 && (flags & PTN_ENT_COMPAT) != 0) {
        *decoded = '"';
        return 1;
    }
    if (value == 39 && (flags & PTN_ENT_SINGLE_QUOTE) != 0) {
        *decoded = '\'';
        return 1;
    }
    return 0;
}

static void ptn_html_append_utf8_codepoint(PtnStringBuffer *output, unsigned int value) {
    if (value <= 0x7f) {
        ptn_string_buffer_append_char(output, (char)value);
    } else if (value <= 0x7ff) {
        ptn_string_buffer_append_char(output, (char)(0xc0 | (value >> 6)));
        ptn_string_buffer_append_char(output, (char)(0x80 | (value & 0x3f)));
    } else if (value <= 0xffff) {
        ptn_string_buffer_append_char(output, (char)(0xe0 | (value >> 12)));
        ptn_string_buffer_append_char(output, (char)(0x80 | ((value >> 6) & 0x3f)));
        ptn_string_buffer_append_char(output, (char)(0x80 | (value & 0x3f)));
    } else if (value <= 0x10ffff) {
        ptn_string_buffer_append_char(output, (char)(0xf0 | (value >> 18)));
        ptn_string_buffer_append_char(output, (char)(0x80 | ((value >> 12) & 0x3f)));
        ptn_string_buffer_append_char(output, (char)(0x80 | ((value >> 6) & 0x3f)));
        ptn_string_buffer_append_char(output, (char)(0x80 | (value & 0x3f)));
    }
}

static int ptn_html_codepoint_allowed(unsigned int value, int64_t flags) {
    if (value == 0 || value > 0x10ffff || (value >= 0xd800 && value <= 0xdfff)) {
        return 0;
    }
    if (value >= 0x20) {
        int64_t doc_type = flags & PTN_ENT_DOC_TYPE_MASK;
        if (doc_type == PTN_ENT_HTML401 && value >= 0x7f && value <= 0x9f) {
            return 0;
        }
        if (doc_type == PTN_ENT_HTML5) {
            if ((value >= 0x7f && value <= 0x9f) ||
                (value >= 0xfdd0 && value <= 0xfdef) ||
                ((value & 0xfffe) == 0xfffe)) {
                return 0;
            }
        }
        if ((doc_type == PTN_ENT_XML1 || doc_type == PTN_ENT_XHTML) &&
            (value == 0xfffe || value == 0xffff)) {
            return 0;
        }
        return 1;
    }
    return value == 0x09 || value == 0x0a || value == 0x0d ||
        (value == 0x0c && (flags & PTN_ENT_DOC_TYPE_MASK) == PTN_ENT_HTML5);
}

static int ptn_html_decode_codepoint_allowed(unsigned int value, int64_t flags) {
    if ((flags & PTN_ENT_DOC_TYPE_MASK) == PTN_ENT_HTML5 && value == 0x0d) {
        return 0;
    }
    return ptn_html_codepoint_allowed(value, flags);
}

#define PTN_HTML_ENTITY_DOC_HTML401 1u
#define PTN_HTML_ENTITY_DOC_XHTML 2u
#define PTN_HTML_ENTITY_DOC_HTML5 4u
#define PTN_HTML_ENTITY_DOC_XML1 8u

typedef struct {
    const char *entity;
    const char *decoded;
    unsigned int docs;
} PtnHtmlNamedEntity;

