static unsigned int ptn_html_entity_doc_mask_for_flags(int64_t flags) {
    switch (flags & PTN_ENT_DOC_TYPE_MASK) {
        case PTN_ENT_HTML401:
            return PTN_HTML_ENTITY_DOC_HTML401;
        case PTN_ENT_XHTML:
            return PTN_HTML_ENTITY_DOC_XHTML;
        case PTN_ENT_HTML5:
            return PTN_HTML_ENTITY_DOC_HTML5;
        case PTN_ENT_XML1:
            return PTN_HTML_ENTITY_DOC_XML1;
        default:
            return PTN_HTML_ENTITY_DOC_HTML401;
    }
}

static int ptn_html_named_entity_allowed_for_doc(const PtnHtmlNamedEntity *entity, int64_t flags) {
    return (entity->docs & ptn_html_entity_doc_mask_for_flags(flags)) != 0;
}

static int ptn_html_named_entity_decodes_to_char(const PtnHtmlNamedEntity *entity, char expected) {
    return entity->decoded[0] == expected && entity->decoded[1] == '\0';
}

static int ptn_html_decode_named_entity(
    const char *data,
    size_t len,
    size_t offset,
    int64_t flags,
    const char **decoded,
    size_t *decoded_len,
    size_t *matched_len
) {
    size_t count = 0;
    const PtnHtmlNamedEntity *entities = ptn_html_named_entities(&count);
    for (size_t i = 0; i < count; i++) {
        if (!ptn_html_named_entity_allowed_for_doc(&entities[i], flags)) {
            continue;
        }
        if ((flags & PTN_ENT_COMPAT) == 0 && ptn_html_named_entity_decodes_to_char(&entities[i], '"')) {
            continue;
        }
        if ((flags & PTN_ENT_SINGLE_QUOTE) == 0 && strcmp(entities[i].decoded, "'") == 0) {
            continue;
        }
        size_t entity_len = strlen(entities[i].entity);
        if (entity_len <= len - offset && memcmp(data + offset, entities[i].entity, entity_len) == 0) {
            *decoded = entities[i].decoded;
            *decoded_len = strlen(entities[i].decoded);
            *matched_len = entity_len;
            return 1;
        }
    }
    return 0;
}

static int ptn_html_ascii_case_equal_literal(const char *data, size_t len, const char *literal) {
    size_t literal_len = strlen(literal);
    if (len != literal_len) {
        return 0;
    }
    for (size_t i = 0; i < len; i++) {
        if (ptn_ascii_lower_byte((unsigned char)data[i]) != ptn_ascii_lower_byte((unsigned char)literal[i])) {
            return 0;
        }
    }
    return 1;
}

static int ptn_html_encoding_from_operand(PtnStringOperand encoding, PtnHtmlEncoding *out) {
    if (encoding.len == 0 ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "UTF-8") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "UTF8")) {
        *out = PTN_HTML_ENCODING_UTF8;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "ISO-8859-1") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "ISO8859-1")) {
        *out = PTN_HTML_ENCODING_ISO_8859_1;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "WINDOWS-1252") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "CP1252") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "1252")) {
        *out = PTN_HTML_ENCODING_WINDOWS_1252;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "CP866") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "IBM866") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "866")) {
        *out = PTN_HTML_ENCODING_CP866;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "ISO-8859-15") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "ISO8859-15")) {
        *out = PTN_HTML_ENCODING_ISO_8859_15;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "ISO-8859-5") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "ISO8859-5")) {
        *out = PTN_HTML_ENCODING_ISO_8859_5;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "KOI8-R")) {
        *out = PTN_HTML_ENCODING_KOI8_R;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "MACROMAN")) {
        *out = PTN_HTML_ENCODING_MACROMAN;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "WINDOWS-1251") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "CP1251")) {
        *out = PTN_HTML_ENCODING_WINDOWS_1251;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "SJIS") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "SHIFT_JIS") ||
        ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "SHIFT-JIS")) {
        *out = PTN_HTML_ENCODING_SJIS;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "EUC-JP")) {
        *out = PTN_HTML_ENCODING_EUC_JP;
        return 1;
    }
    if (ptn_html_ascii_case_equal_literal(encoding.data, encoding.len, "BIG5")) {
        *out = PTN_HTML_ENCODING_LEGACY_MULTIBYTE;
        return 1;
    }
    return 0;
}

static int ptn_html_encoding_is_legacy_multibyte(PtnHtmlEncoding encoding) {
    return encoding == PTN_HTML_ENCODING_SJIS ||
        encoding == PTN_HTML_ENCODING_EUC_JP ||
        encoding == PTN_HTML_ENCODING_LEGACY_MULTIBYTE;
}

static int ptn_html_should_replace_disallowed(
    PtnHtmlEscapeMode mode,
    unsigned int codepoint,
    int64_t flags,
    PtnHtmlEncoding encoding
) {
    if ((flags & PTN_ENT_DISALLOWED) == 0 || ptn_html_codepoint_allowed(codepoint, flags)) {
        return 0;
    }
    int64_t doc_type = flags & PTN_ENT_DOC_TYPE_MASK;
    if (mode == PTN_HTML_ESCAPE_SPECIALCHARS &&
        encoding != PTN_HTML_ENCODING_UTF8 &&
        doc_type != PTN_ENT_XML1 &&
        doc_type != PTN_ENT_XHTML &&
        codepoint >= 0x7f && codepoint <= 0x9f) {
        return 0;
    }
    return 1;
}

static void ptn_html_emit_unsupported_encoding_warning(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand encoding,
    size_t line
) {
    int needed = snprintf(
        NULL,
        0,
        "%s(): Charset \"%.*s\" is not supported, assuming UTF-8",
        function_name,
        (int)encoding.len,
        encoding.data
    );
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(
        message,
        (size_t)needed + 1,
        "%s(): Charset \"%.*s\" is not supported, assuming UTF-8",
        function_name,
        (int)encoding.len,
        encoding.data
    );
    ptn_emit_warning(&runtime->diagnostics, message, line);
    free(message);
}

static PtnHtmlEncoding ptn_html_optional_encoding(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line
) {
    if (argc < 3 || ptn_value_deref(args[2]).type == PTN_NULL) {
        return PTN_HTML_ENCODING_UTF8;
    }
    PtnStringOperand encoding =
        ptn_internal_expect_string_arg(runtime, function_name, 3, "encoding", args[2], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(encoding);
        return PTN_HTML_ENCODING_UTF8;
    }
    PtnHtmlEncoding result = PTN_HTML_ENCODING_UTF8;
    if (!ptn_html_encoding_from_operand(encoding, &result)) {
        ptn_html_emit_unsupported_encoding_warning(runtime, function_name, encoding, line);
        result = PTN_HTML_ENCODING_UTF8;
    }
    ptn_string_operand_free(encoding);
    return result;
}

static int ptn_html_utf8_codepoint(const char *data, size_t len, unsigned int *codepoint) {
    if (len == 1) {
        *codepoint = (unsigned char)data[0];
        return 1;
    }
    if (len == 2) {
        unsigned char first = (unsigned char)data[0];
        unsigned char second = (unsigned char)data[1];
        if ((first & 0xe0) == 0xc0 && (second & 0xc0) == 0x80) {
            *codepoint = ((unsigned int)(first & 0x1f) << 6) | (unsigned int)(second & 0x3f);
            return *codepoint >= 0x80;
        }
        return 0;
    }
    if (len == 3) {
        unsigned char first = (unsigned char)data[0];
        unsigned char second = (unsigned char)data[1];
        unsigned char third = (unsigned char)data[2];
        if ((first & 0xf0) == 0xe0 && (second & 0xc0) == 0x80 && (third & 0xc0) == 0x80) {
            *codepoint =
                ((unsigned int)(first & 0x0f) << 12) |
                ((unsigned int)(second & 0x3f) << 6) |
                (unsigned int)(third & 0x3f);
            return *codepoint >= 0x800;
        }
        return 0;
    }
    if (len == 4) {
        unsigned char first = (unsigned char)data[0];
        unsigned char second = (unsigned char)data[1];
        unsigned char third = (unsigned char)data[2];
        unsigned char fourth = (unsigned char)data[3];
        if ((first & 0xf8) == 0xf0 &&
            (second & 0xc0) == 0x80 &&
            (third & 0xc0) == 0x80 &&
            (fourth & 0xc0) == 0x80) {
            *codepoint =
                ((unsigned int)(first & 0x07) << 18) |
                ((unsigned int)(second & 0x3f) << 12) |
                ((unsigned int)(third & 0x3f) << 6) |
                (unsigned int)(fourth & 0x3f);
            return *codepoint >= 0x10000 && *codepoint <= 0x10ffff;
        }
    }
    return 0;
}

static size_t ptn_html_utf8_expected_len(unsigned char first) {
    if (first < 0x80) {
        return 1;
    }
    if (first >= 0xc0 && first <= 0xdf) {
        return 2;
    }
    if (first >= 0xe0 && first <= 0xef) {
        return 3;
    }
    if (first >= 0xf0 && first <= 0xf4) {
        return 4;
    }
    return 0;
}

static int ptn_html_read_utf8(
    const char *data,
    size_t len,
    size_t offset,
    unsigned int *codepoint,
    size_t *sequence_len
) {
    if (offset >= len) {
        return 0;
    }
    size_t expected = ptn_html_utf8_expected_len((unsigned char)data[offset]);
    if (expected == 0 || expected > len - offset) {
        return 0;
    }
    for (size_t i = 1; i < expected; i++) {
        if (((unsigned char)data[offset + i] & 0xc0) != 0x80) {
            return 0;
        }
    }
    if (!ptn_html_utf8_codepoint(data + offset, expected, codepoint)) {
        return 0;
    }
    if (*codepoint >= 0xd800 && *codepoint <= 0xdfff) {
        return 0;
    }
    *sequence_len = expected;
    return 1;
}

static size_t ptn_html_invalid_utf8_len(const char *data, size_t len, size_t offset) {
    if (offset >= len) {
        return 0;
    }
    size_t expected = ptn_html_utf8_expected_len((unsigned char)data[offset]);
    if (expected == 0) {
        return 1;
    }
    size_t consumed = 1;
    while (consumed < expected && offset + consumed < len) {
        if (((unsigned char)data[offset + consumed] & 0xc0) != 0x80) {
            break;
        }
        consumed++;
    }
    return consumed;
}

