static const char *ptn_html_html5_canonical_entity_for_decoded(const char *decoded, size_t decoded_len) {
    size_t count = 0;
    const PtnHtmlCanonicalEntity *entities = ptn_html_html5_canonical_entities(&count);
    for (size_t i = 0; i < count; i++) {
        if (entities[i].decoded_len == decoded_len &&
            memcmp(entities[i].decoded, decoded, decoded_len) == 0) {
            return entities[i].entity;
        }
    }
    return NULL;
}

static int ptn_html_entity_is_html5_canonical_alias(const char *entity) {
    size_t count = 0;
    const PtnHtmlCanonicalEntity *entities = ptn_html_html5_canonical_entities(&count);
    for (size_t i = 0; i < count; i++) {
        if (strcmp(entities[i].entity, entity) == 0) {
            return 1;
        }
    }
    return 0;
}

static int ptn_html_html5_canonical_entity_at(
    const char *data,
    size_t len,
    size_t offset,
    const char **entity,
    size_t *matched_len
) {
    size_t count = 0;
    const PtnHtmlCanonicalEntity *entities = ptn_html_html5_canonical_entities(&count);
    for (size_t i = 0; i < count; i++) {
        if (entities[i].decoded_len <= len - offset &&
            entities[i].decoded[0] == data[offset] &&
            memcmp(data + offset, entities[i].decoded, entities[i].decoded_len) == 0) {
            *entity = entities[i].entity;
            *matched_len = entities[i].decoded_len;
            return 1;
        }
    }
    return 0;
}

static int ptn_html_encoded_key_for_decoded(
    const char *decoded,
    size_t decoded_len,
    PtnHtmlEncoding encoding,
    PtnStringBuffer *key
) {
    return ptn_html_append_decoded_entity_encoded(key, decoded, decoded_len, encoding);
}

static void ptn_html_translation_table_set_entity(PtnValue table, PtnArrayKey key, const char *entity) {
    PtnArrayEntry *entry = ptn_array_entry_for_key(table.as.array, key);
    if (entry != NULL) {
        PtnValue current = ptn_value_deref(entry->value);
        if (current.type == PTN_STRING &&
            ptn_html_entity_should_replace_alias((const char *)current.as.string.data, entity)) {
            ptn_value_destroy(&entry->value);
            entry->value = ptn_string(entity);
        }
        ptn_array_key_free(key);
        return;
    }
    ptn_array_set_entry(table.as.array, key, ptn_string(entity));
}

static void ptn_html_translation_table_add_encoded(
    PtnValue table,
    const char *decoded,
    const char *entity,
    PtnHtmlEncoding encoding
) {
    PtnStringBuffer key;
    ptn_string_buffer_init(&key);
    if (!ptn_html_encoded_key_for_decoded(decoded, strlen(decoded), encoding, &key)) {
        free(key.data);
        return;
    }
    ptn_html_translation_table_set_entity(table, ptn_array_string_key_len(key.data, key.len), entity);
    free(key.data);
}

static void ptn_html_translation_table_add_special(PtnValue table, int64_t flags, PtnHtmlEncoding encoding) {
    int64_t doc_type = flags & PTN_ENT_DOC_TYPE_MASK;
    ptn_html_translation_table_add_encoded(table, "&", "&amp;", encoding);
    ptn_html_translation_table_add_encoded(table, "<", "&lt;", encoding);
    ptn_html_translation_table_add_encoded(table, ">", "&gt;", encoding);
    if ((flags & PTN_ENT_COMPAT) != 0) {
        ptn_html_translation_table_add_encoded(table, "\"", "&quot;", encoding);
    }
    if ((flags & PTN_ENT_SINGLE_QUOTE) != 0) {
        ptn_html_translation_table_add_encoded(
            table,
            "'",
            doc_type == PTN_ENT_HTML401 ? "&#039;" : "&apos;",
            encoding
        );
    }
}

static PtnValue ptn_internal_get_html_translation_table(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int64_t table_kind = argc >= 1
        ? ptn_internal_expect_integer_arg(runtime, "get_html_translation_table", 1, "table", args[0], line)
        : PTN_HTML_SPECIALCHARS;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    int64_t flags = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "get_html_translation_table", 2, "flags", args[1], line)
        : PTN_HTML_DEFAULT_FLAGS;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnHtmlEncoding encoding = ptn_html_optional_encoding(runtime, "get_html_translation_table", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnValue table = ptn_array_from_literal_entries(0, NULL);
    if (table_kind == PTN_HTML_ENTITIES &&
        (flags & PTN_ENT_DOC_TYPE_MASK) != PTN_ENT_XML1 &&
        !ptn_html_encoding_is_legacy_multibyte(encoding)) {
        size_t count = 0;
        const PtnHtmlNamedEntity *entities = ptn_html_named_entities(&count);
        for (size_t i = 0; i < count; i++) {
            if ((flags & PTN_ENT_COMPAT) == 0 && ptn_html_named_entity_decodes_to_char(&entities[i], '"')) {
                continue;
            }
            if ((flags & PTN_ENT_SINGLE_QUOTE) == 0 && strcmp(entities[i].decoded, "'") == 0) {
                continue;
            }
            if (!ptn_html_entity_allowed_for_doc(&entities[i], flags)) {
                continue;
            }
            const char *entity = entities[i].entity;
            if ((flags & PTN_ENT_DOC_TYPE_MASK) == PTN_ENT_XHTML && strcmp(entities[i].decoded, "'") == 0) {
                entity = "&#039;";
            }
            ptn_html_translation_table_add_encoded(table, entities[i].decoded, entity, encoding);
        }
    } else {
        ptn_html_translation_table_add_special(table, flags, encoding);
    }
    return table;
}

static int ptn_html_any_entity_len_at(
    const char *data,
    size_t len,
    size_t offset,
    int64_t flags,
    size_t *matched_len
) {
    unsigned int numeric_value = 0;
    if (ptn_html_numeric_entity_value(data, len, offset, matched_len, &numeric_value)) {
        if (numeric_value > 0x10ffff) {
            return 0;
        }
        if ((flags & PTN_ENT_DISALLOWED) == 0) {
            return 1;
        }
        int64_t doc_type = flags & PTN_ENT_DOC_TYPE_MASK;
        if (doc_type == PTN_ENT_HTML401) {
            return 1;
        }
        if (doc_type == PTN_ENT_HTML5) {
            if (numeric_value == 0 ||
                (numeric_value < 0x20 &&
                    numeric_value != 0x09 &&
                    numeric_value != 0x0a &&
                    numeric_value != 0x0c) ||
                (numeric_value >= 0x7f && numeric_value <= 0x9f) ||
                (numeric_value >= 0xfdd0 && numeric_value <= 0xfdef) ||
                ((numeric_value & 0xfffe) == 0xfffe)) {
                return 0;
            }
            return 1;
        }
        if (numeric_value == 0 ||
            (numeric_value < 0x20 &&
                numeric_value != 0x09 &&
                numeric_value != 0x0a &&
                numeric_value != 0x0d) ||
            (numeric_value >= 0xd800 && numeric_value <= 0xdfff) ||
            numeric_value == 0xfffe ||
            numeric_value == 0xffff) {
            return 0;
        }
        return 1;
    }
    const char *decoded = NULL;
    size_t decoded_len = 0;
    return ptn_html_decode_named_entity(
        data,
        len,
        offset,
        PTN_ENT_QUOTES | PTN_ENT_HTML5,
        &decoded,
        &decoded_len,
        matched_len
    );
}

static int ptn_html_entity_allowed_for_doc(const PtnHtmlNamedEntity *entity, int64_t flags) {
    return ptn_html_named_entity_allowed_for_doc(entity, flags);
}

static const char *ptn_html_entity_for_codepoint(unsigned int codepoint, int64_t flags) {
    int64_t doc_type = flags & PTN_ENT_DOC_TYPE_MASK;
    if (doc_type == PTN_ENT_HTML5) {
        if (codepoint == '#') {
            return "&num;";
        }
        if (codepoint == ';') {
            return "&semi;";
        }
        if (codepoint == 0x09) {
            return "&Tab;";
        }
        if (codepoint == 0x0a) {
            return "&NewLine;";
        }
        PtnStringBuffer decoded;
        ptn_string_buffer_init(&decoded);
        ptn_html_append_utf8_codepoint(&decoded, codepoint);
        const char *canonical =
            ptn_html_html5_canonical_entity_for_decoded(decoded.data, decoded.len);
        free(decoded.data);
        if (canonical != NULL) {
            return canonical;
        }
    }
    const char *match = NULL;
    size_t count = 0;
    const PtnHtmlNamedEntity *entities = ptn_html_named_entities(&count);
    for (size_t i = 0; i < count; i++) {
        unsigned int entity_codepoint = 0;
        if (!ptn_html_decoded_entity_codepoint(
                entities[i].decoded,
                strlen(entities[i].decoded),
                &entity_codepoint
            )) {
            continue;
        }
        if (entity_codepoint != codepoint) {
            continue;
        }
        if (!ptn_html_entity_allowed_for_doc(&entities[i], flags)) {
            continue;
        }
        if ((flags & PTN_ENT_COMPAT) == 0 && ptn_html_named_entity_decodes_to_char(&entities[i], '"')) {
            continue;
        }
        if ((flags & PTN_ENT_SINGLE_QUOTE) == 0 &&
            (strcmp(entities[i].entity, "&#039;") == 0 || strcmp(entities[i].decoded, "'") == 0)) {
            continue;
        }
        if (match == NULL || ptn_html_entity_should_replace_alias(match, entities[i].entity)) {
            match = entities[i].entity;
        }
    }
    return match;
}

static void ptn_html_append_replacement_character(PtnStringBuffer *output) {
    ptn_string_buffer_append(output, "\357\277\275");
}

static void ptn_html_append_replacement_character_for_encoding(
    PtnStringBuffer *output,
    PtnHtmlEncoding encoding
) {
    if (encoding == PTN_HTML_ENCODING_UTF8) {
        ptn_html_append_replacement_character(output);
    } else {
        ptn_string_buffer_append(output, "&#xFFFD;");
    }
}

static void ptn_html_append_escaped_codepoint(
    PtnStringBuffer *output,
    unsigned int codepoint,
    const char *original,
    size_t original_len,
    int64_t flags,
    PtnHtmlEscapeMode mode
) {
    switch (codepoint) {
        case '&':
            ptn_string_buffer_append(output, "&amp;");
            return;
        case '<':
            ptn_string_buffer_append(output, "&lt;");
            return;
        case '>':
            ptn_string_buffer_append(output, "&gt;");
            return;
        case '"':
            if ((flags & PTN_ENT_COMPAT) != 0) {
                ptn_string_buffer_append(output, "&quot;");
            } else {
                ptn_string_buffer_append_len(output, original, original_len);
            }
            return;
        case '\'':
            if ((flags & PTN_ENT_SINGLE_QUOTE) != 0) {
                ptn_string_buffer_append(
                    output,
                    (flags & PTN_ENT_DOC_TYPE_MASK) == PTN_ENT_HTML401 ? "&#039;" : "&apos;"
                );
            } else {
                ptn_string_buffer_append_len(output, original, original_len);
            }
            return;
        default:
            break;
    }

    if (mode == PTN_HTML_ESCAPE_ENTITIES) {
        const char *entity = ptn_html_entity_for_codepoint(codepoint, flags);
        if (entity != NULL) {
            ptn_string_buffer_append(output, entity);
            return;
        }
    }
    ptn_string_buffer_append_len(output, original, original_len);
}

static int ptn_html_escape_utf8_string(
    PtnStringBuffer *output,
    PtnStringOperand string,
    int64_t flags,
    int double_encode,
    PtnHtmlEscapeMode mode
) {
    for (size_t i = 0; i < string.len;) {
        if (!double_encode && string.data[i] == '&') {
            size_t entity_len = 0;
            if (ptn_html_any_entity_len_at(string.data, string.len, i, flags, &entity_len)) {
                ptn_string_buffer_append_len(output, string.data + i, entity_len);
                i += entity_len;
                continue;
            }
        }

        unsigned int codepoint = 0;
        size_t sequence_len = 0;
        if (!ptn_html_read_utf8(string.data, string.len, i, &codepoint, &sequence_len)) {
            size_t invalid_len = ptn_html_invalid_utf8_len(string.data, string.len, i);
            if ((flags & PTN_ENT_IGNORE) != 0) {
                i += invalid_len;
                continue;
            }
            if ((flags & PTN_ENT_SUBSTITUTE) != 0) {
                ptn_html_append_replacement_character(output);
                i += invalid_len;
                continue;
            }
            return 0;
        }

        if (ptn_html_should_replace_disallowed(mode, codepoint, flags, PTN_HTML_ENCODING_UTF8)) {
            ptn_html_append_replacement_character(output);
            i += sequence_len;
            continue;
        }

        if (mode == PTN_HTML_ESCAPE_ENTITIES &&
            (flags & PTN_ENT_DOC_TYPE_MASK) == PTN_ENT_HTML5) {
            const char *canonical = NULL;
            size_t canonical_len = 0;
            if (ptn_html_html5_canonical_entity_at(
                    string.data,
                    string.len,
                    i,
                    &canonical,
                    &canonical_len
                )) {
                ptn_string_buffer_append(output, canonical);
                i += canonical_len;
                continue;
            }
        }

        ptn_html_append_escaped_codepoint(
            output,
            codepoint,
            string.data + i,
            sequence_len,
            flags,
            mode
        );
        i += sequence_len;
    }
    return 1;
}

static unsigned int ptn_html_windows_1252_codepoint_for_byte(unsigned char byte) {
    switch (byte) {
        case 0x80: return 0x20ac;
        case 0x82: return 0x201a;
        case 0x83: return 0x0192;
        case 0x84: return 0x201e;
        case 0x85: return 0x2026;
        case 0x86: return 0x2020;
        case 0x87: return 0x2021;
        case 0x88: return 0x02c6;
        case 0x89: return 0x2030;
        case 0x8a: return 0x0160;
        case 0x8b: return 0x2039;
        case 0x8c: return 0x0152;
        case 0x8e: return 0x017d;
        case 0x91: return 0x2018;
        case 0x92: return 0x2019;
        case 0x93: return 0x201c;
        case 0x94: return 0x201d;
        case 0x95: return 0x2022;
        case 0x96: return 0x2013;
        case 0x97: return 0x2014;
        case 0x98: return 0x02dc;
        case 0x99: return 0x2122;
        case 0x9a: return 0x0161;
        case 0x9b: return 0x203a;
        case 0x9c: return 0x0153;
        case 0x9e: return 0x017e;
        case 0x9f: return 0x0178;
        default:
            return (unsigned int)byte;
    }
}

static int ptn_html_sjis_trail_byte(unsigned char byte) {
    return (byte >= 0x40 && byte <= 0x7e) || (byte >= 0x80 && byte <= 0xfc);
}

static int ptn_html_legacy_multibyte_sequence(
    PtnHtmlEncoding encoding,
    const char *data,
    size_t len,
    size_t offset,
    size_t *sequence_len,
    int *valid
) {
    unsigned char byte = (unsigned char)data[offset];
    *sequence_len = 1;
    *valid = 1;
    if (byte <= 0x7f) {
        return 1;
    }
    if (encoding == PTN_HTML_ENCODING_SJIS) {
        if (byte >= 0xa1 && byte <= 0xdf) {
            return 1;
        }
        if ((byte >= 0x81 && byte <= 0x9f) || (byte >= 0xe0 && byte <= 0xfc)) {
            if (offset + 1 < len && ptn_html_sjis_trail_byte((unsigned char)data[offset + 1])) {
                *sequence_len = 2;
                return 1;
            }
            *valid = 0;
            return 1;
        }
        *valid = 0;
        return 1;
    }
    if (encoding == PTN_HTML_ENCODING_EUC_JP) {
        if (byte == 0x8e) {
            if (offset + 1 < len && (unsigned char)data[offset + 1] >= 0xa1 &&
                (unsigned char)data[offset + 1] <= 0xdf) {
                *sequence_len = 2;
                return 1;
            }
            *valid = 0;
            return 1;
        }
        if (byte == 0x8f) {
            if (offset + 1 >= len) {
                *valid = 0;
                return 1;
            }
            unsigned char second = (unsigned char)data[offset + 1];
            if (second < 0x80) {
                *valid = 0;
                return 1;
            }
            if (second < 0xa1 || second > 0xfe) {
                *sequence_len = 2;
                *valid = 0;
                return 1;
            }
            if (offset + 2 < len && (unsigned char)data[offset + 2] >= 0xa1 &&
                (unsigned char)data[offset + 2] <= 0xfe) {
                *sequence_len = 3;
                return 1;
            }
            *valid = 0;
            return 1;
        }
        if (byte >= 0xa1 && byte <= 0xfe) {
            if (offset + 1 < len && (unsigned char)data[offset + 1] >= 0xa1 &&
                (unsigned char)data[offset + 1] <= 0xfe) {
                *sequence_len = 2;
                return 1;
            }
            if (offset + 1 < len && (unsigned char)data[offset + 1] >= 0x80) {
                *sequence_len = 2;
            }
            *valid = 0;
            return 1;
        }
        *valid = 0;
        return 1;
    }
    return 0;
}

static int ptn_html_escape_byte_string(
    PtnStringBuffer *output,
    PtnStringOperand string,
    int64_t flags,
    int double_encode,
    PtnHtmlEscapeMode mode,
    PtnHtmlEncoding encoding
) {
    for (size_t i = 0; i < string.len; i++) {
        if (ptn_html_encoding_is_legacy_multibyte(encoding)) {
            size_t sequence_len = 1;
            int valid_sequence = 1;
            if (ptn_html_legacy_multibyte_sequence(
                    encoding,
                    string.data,
                    string.len,
                    i,
                    &sequence_len,
                    &valid_sequence
                )) {
                if (!valid_sequence) {
                    if ((flags & PTN_ENT_IGNORE) != 0) {
                        i += sequence_len - 1;
                        continue;
                    }
                    if ((flags & PTN_ENT_SUBSTITUTE) != 0) {
                        ptn_html_append_replacement_character_for_encoding(output, encoding);
                        i += sequence_len - 1;
                        continue;
                    }
                    return 0;
                }
                if (sequence_len > 1) {
                    ptn_string_buffer_append_len(output, string.data + i, sequence_len);
                    i += sequence_len - 1;
                    continue;
                }
            }
        }
        if (!double_encode && string.data[i] == '&') {
            size_t entity_len = 0;
            if (ptn_html_any_entity_len_at(string.data, string.len, i, flags, &entity_len)) {
                ptn_string_buffer_append_len(output, string.data + i, entity_len);
                i += entity_len - 1;
                continue;
            }
        }
        unsigned char byte = (unsigned char)string.data[i];
        unsigned int codepoint = encoding == PTN_HTML_ENCODING_WINDOWS_1252
            ? ptn_html_windows_1252_codepoint_for_byte(byte)
            : ptn_html_single_byte_codepoint_for_byte(encoding, byte);
        char original[1] = { (char)byte };
        if (ptn_html_should_replace_disallowed(mode, codepoint, flags, encoding)) {
            ptn_html_append_replacement_character_for_encoding(output, encoding);
            continue;
        }
        ptn_html_append_escaped_codepoint(output, codepoint, original, 1, flags, mode);
    }
    return 1;
}

static PtnValue ptn_html_escape_value(
    PtnStringOperand string,
    int64_t flags,
    int double_encode,
    PtnHtmlEscapeMode mode,
    PtnHtmlEncoding encoding
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    int ok = encoding == PTN_HTML_ENCODING_UTF8
        ? ptn_html_escape_utf8_string(&output, string, flags, double_encode, mode)
        : ptn_html_escape_byte_string(&output, string, flags, double_encode, mode, encoding);
    if (!ok) {
        free(output.data);
        return ptn_string("");
    }
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_htmlspecialchars(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "htmlspecialchars", 1, "string", args[0], line);
    int64_t flags = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "htmlspecialchars", 2, "flags", args[1], line)
        : PTN_HTML_DEFAULT_FLAGS;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(string);
        return ptn_null();
    }
    PtnHtmlEncoding encoding = ptn_html_optional_encoding(runtime, "htmlspecialchars", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(string);
        return ptn_null();
    }
    int double_encode = argc < 4 || ptn_is_truthy(args[3]);
    PtnValue result = ptn_html_escape_value(
        string,
        flags,
        double_encode,
        PTN_HTML_ESCAPE_SPECIALCHARS,
        encoding
    );
    ptn_string_operand_free(string);
    return result;
}

static PtnValue ptn_internal_htmlentities(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "htmlentities", 1, "string", args[0], line);
    int64_t flags = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "htmlentities", 2, "flags", args[1], line)
        : PTN_HTML_DEFAULT_FLAGS;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(string);
        return ptn_null();
    }
    PtnHtmlEncoding encoding = ptn_html_optional_encoding(runtime, "htmlentities", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (ptn_html_encoding_is_legacy_multibyte(encoding)) {
        if (ptn_diagnostics_should_emit(&runtime->diagnostics, PTN_E_NOTICE)) {
            fputc('\n', stdout);
        }
        ptn_emit_notice(
            &runtime->diagnostics,
            "htmlentities(): Only basic entities substitution is supported for multi-byte encodings other than UTF-8; functionality is equivalent to htmlspecialchars",
            line
        );
    }
    int double_encode = argc < 4 || ptn_is_truthy(args[3]);
    PtnHtmlEscapeMode mode = ptn_html_encoding_is_legacy_multibyte(encoding)
        ? PTN_HTML_ESCAPE_SPECIALCHARS
        : PTN_HTML_ESCAPE_ENTITIES;
    PtnValue result = ptn_html_escape_value(
        string,
        flags,
        double_encode,
        mode,
        encoding
    );
    ptn_string_operand_free(string);
    return result;
}

static PtnValue ptn_internal_htmlspecialchars_decode(
    PtnRuntime *runtime,
    size_t argc,
    const PtnValue *args,
    size_t line
) {
    PtnStringOperand string =
        ptn_internal_expect_string_arg(runtime, "htmlspecialchars_decode", 1, "string", args[0], line);
    int64_t flags = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "htmlspecialchars_decode", 2, "flags", args[1], line)
        : PTN_HTML_DEFAULT_FLAGS;

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < string.len; i++) {
        if (string.data[i] == '&') {
            char decoded = '\0';
            size_t entity_len = 0;
            if (ptn_html_entity_decode_char(string.data, string.len, i, flags, &decoded, &entity_len)) {
                ptn_string_buffer_append_char(&output, decoded);
                i += entity_len - 1;
                continue;
            }
        }
        ptn_string_buffer_append_char(&output, string.data[i]);
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_wordwrap_break_at(PtnStringOperand input, PtnStringOperand break_string, size_t offset) {
    return break_string.len <= input.len - offset &&
           memcmp(input.data + offset, break_string.data, break_string.len) == 0;
}

static size_t ptn_wordwrap_next_word_len(PtnStringOperand segment, PtnStringOperand break_string, size_t offset) {
    size_t cursor = offset;
    while (cursor < segment.len &&
           segment.data[cursor] != ' ' &&
           !ptn_wordwrap_break_at(segment, break_string, cursor)) {
        cursor++;
    }
    return cursor - offset;
}

static void ptn_wordwrap_append_wrapped_segment(
    PtnStringBuffer *output,
    PtnStringOperand segment,
    PtnStringOperand break_string,
    size_t width,
    int cut_long_words
) {
    size_t line_len = 0;
    for (size_t i = 0; i < segment.len; i++) {
        if (ptn_wordwrap_break_at(segment, break_string, i)) {
            ptn_string_buffer_append_len(output, break_string.data, break_string.len);
            i += break_string.len - 1;
            line_len = 0;
            continue;
        }

        if (segment.data[i] == ' ') {
            size_t next_word_len = i + 1 < segment.len
                ? ptn_wordwrap_next_word_len(segment, break_string, i + 1)
                : 0;
            if (line_len >= width ||
                (line_len > 0 && next_word_len > 0 && line_len + 1 + next_word_len > width)) {
                ptn_string_buffer_append_len(output, break_string.data, break_string.len);
                line_len = 0;
            } else {
                ptn_string_buffer_append_char(output, ' ');
                line_len++;
            }
            continue;
        }

        if (cut_long_words && line_len >= width) {
            ptn_string_buffer_append_len(output, break_string.data, break_string.len);
            line_len = 0;
        }
        ptn_string_buffer_append_char(output, segment.data[i]);
        line_len++;
    }
}

static PtnValue ptn_wordwrap_width_not_positive(
    PtnStringOperand string,
    PtnStringOperand break_string,
    int64_t width,
    int cut_long_words
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    if (cut_long_words && width < 0) {
        for (size_t i = 0; i < string.len; i++) {
            ptn_string_buffer_append_len(&output, break_string.data, break_string.len);
            if (string.data[i] != ' ') {
                ptn_string_buffer_append_char(&output, string.data[i]);
            }
        }
        return ptn_owned_string_len(output.data, output.len);
    }

    for (size_t i = 0; i < string.len; i++) {
        if (string.data[i] == ' ') {
            ptn_string_buffer_append_len(&output, break_string.data, break_string.len);
        } else {
            ptn_string_buffer_append_char(&output, string.data[i]);
        }
    }
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_wordwrap(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "wordwrap", 1, "string", args[0], line);
    int64_t width = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "wordwrap", 2, "width", args[1], line)
        : 75;
    PtnStringOperand break_string = argc >= 3
        ? ptn_internal_expect_string_arg(runtime, "wordwrap", 3, "break", args[2], line)
        : ptn_string_operand_borrowed("\n");
    int cut_long_words = argc >= 4 && ptn_is_truthy(args[3]);

    if (break_string.len == 0) {
        ptn_string_operand_free(string);
        ptn_string_operand_free(break_string);
        ptn_throw_exception(runtime, "ValueError", "wordwrap(): Argument #3 ($break) must not be empty");
        return ptn_null();
    }
    if (width == 0 && cut_long_words) {
        ptn_string_operand_free(string);
        ptn_string_operand_free(break_string);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "wordwrap(): Argument #4 ($cut_long_words) cannot be true when argument #2 ($width) is 0"
        );
        return ptn_null();
    }
    if (width <= 0) {
        PtnValue result = ptn_wordwrap_width_not_positive(string, break_string, width, cut_long_words);
        ptn_string_operand_free(string);
        ptn_string_operand_free(break_string);
        return result;
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    PtnStringOperand segment = ptn_string_operand_borrowed("");
    size_t segment_start = 0;
    for (size_t i = 0; i < string.len;) {
        if (ptn_wordwrap_break_at(string, break_string, i)) {
            segment.data = string.data + segment_start;
            segment.len = i - segment_start;
            ptn_wordwrap_append_wrapped_segment(&output, segment, break_string, (size_t)width, cut_long_words);
            ptn_string_buffer_append_len(&output, break_string.data, break_string.len);
            i += break_string.len;
            segment_start = i;
            continue;
        }
        i++;
    }
    segment.data = string.data + segment_start;
    segment.len = string.len - segment_start;
    ptn_wordwrap_append_wrapped_segment(&output, segment, break_string, (size_t)width, cut_long_words);

    ptn_string_operand_free(string);
    ptn_string_operand_free(break_string);
    return ptn_owned_string_len(output.data, output.len);
}

static void ptn_number_format_append_grouped_integer(
    PtnStringBuffer *output,
    const char *digits,
    PtnStringOperand thousands_separator
) {
    size_t len = strlen(digits);
    size_t first_group_len = len % 3;
    if (first_group_len == 0) {
        first_group_len = 3;
    }
    ptn_string_buffer_append_len(output, digits, first_group_len);
    for (size_t i = first_group_len; i < len; i += 3) {
        ptn_string_buffer_append_len(output, thousands_separator.data, thousands_separator.len);
        ptn_string_buffer_append_len(output, digits + i, 3);
    }
}

static PtnValue ptn_internal_number_format(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    double number = ptn_internal_expect_numeric_arg(runtime, "number_format", 1, "num", args[0], line);
    int64_t decimals_arg = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "number_format", 2, "decimals", args[1], line)
        : 0;
    if (decimals_arg < 0) {
        decimals_arg = 0;
    }
    if (decimals_arg > 18) {
        decimals_arg = 18;
    }
    size_t decimals = (size_t)decimals_arg;
    PtnStringOperand decimal_separator = argc >= 3
        ? ptn_internal_expect_string_arg(runtime, "number_format", 3, "decimal_separator", args[2], line)
        : ptn_string_operand_borrowed(".");
    PtnStringOperand thousands_separator = argc >= 4
        ? ptn_internal_expect_string_arg(runtime, "number_format", 4, "thousands_separator", args[3], line)
        : ptn_string_operand_borrowed(",");

    uint64_t scale = 1;
    for (size_t i = 0; i < decimals; i++) {
        scale *= 10;
    }
    double rounded_scaled = floor(fabs(number) * (double)scale + 0.5);
    uint64_t scaled = rounded_scaled > (double)UINT64_MAX ? UINT64_MAX : (uint64_t)rounded_scaled;
    uint64_t integer_part = scaled / scale;
    uint64_t fractional_part = scaled % scale;

    char integer_digits[64];
    int integer_len = snprintf(integer_digits, sizeof(integer_digits), "%llu", (unsigned long long)integer_part);
    if (integer_len < 0 || (size_t)integer_len >= sizeof(integer_digits)) {
        ptn_abort_out_of_memory();
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    if (number < 0.0 && (integer_part != 0 || fractional_part != 0)) {
        ptn_string_buffer_append_char(&output, '-');
    }
    ptn_number_format_append_grouped_integer(&output, integer_digits, thousands_separator);
    if (decimals > 0) {
        char fractional_digits[32];
        int fractional_len = snprintf(
            fractional_digits,
            sizeof(fractional_digits),
            "%0*llu",
            (int)decimals,
            (unsigned long long)fractional_part
        );
        if (fractional_len < 0 || (size_t)fractional_len >= sizeof(fractional_digits)) {
            ptn_abort_out_of_memory();
        }
        ptn_string_buffer_append_len(&output, decimal_separator.data, decimal_separator.len);
        ptn_string_buffer_append_len(&output, fractional_digits, (size_t)fractional_len);
    }

    ptn_string_operand_free(decimal_separator);
    ptn_string_operand_free(thousands_separator);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_strcmp(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand left = ptn_internal_expect_string_arg(runtime, "strcmp", 1, "string1", args[0], line);
    PtnStringOperand right = ptn_internal_expect_string_arg(runtime, "strcmp", 2, "string2", args[1], line);
    int compared = ptn_compare_string_bytes_php_result(
        (const unsigned char *)left.data,
        left.len,
        (const unsigned char *)right.data,
        right.len
    );
    ptn_string_operand_free(left);
    ptn_string_operand_free(right);
    return ptn_int(compared);
}

