static int ptn_string_window_from_offset_length(
    PtnRuntime *runtime,
    const char *function_name,
    size_t offset_position,
    const char *offset_name,
    size_t length_position,
    const char *length_name,
    size_t string_len,
    int64_t raw_offset,
    int has_length,
    int64_t raw_length,
    size_t *start_out,
    size_t *end_out
) {
    (void)offset_position;
    (void)offset_name;
    size_t start = 0;
    if (raw_offset < 0) {
        uint64_t distance = raw_offset == INT64_MIN
            ? ((uint64_t)INT64_MAX + 1)
            : (uint64_t)(-raw_offset);
        if (distance > (uint64_t)string_len) {
            start = 0;
        } else {
            start = string_len - (size_t)distance;
        }
    } else {
        if ((uint64_t)raw_offset > (uint64_t)string_len) {
            start = string_len;
        } else {
            start = (size_t)raw_offset;
        }
    }

    size_t end = string_len;
    if (has_length) {
        if (raw_length >= 0) {
            uint64_t requested = (uint64_t)raw_length;
            size_t remaining = string_len - start;
            end = requested > (uint64_t)remaining ? string_len : start + (size_t)requested;
        } else {
            uint64_t trim = raw_length == INT64_MIN
                ? ((uint64_t)INT64_MAX + 1)
                : (uint64_t)(-raw_length);
            if (trim > (uint64_t)string_len) {
                char message[160];
                int written = snprintf(
                    message,
                    sizeof(message),
                    "%s(): Argument #%zu ($%s) must be contained in argument #1 ($string)",
                    function_name,
                    length_position,
                    length_name
                );
                if (written < 0 || (size_t)written >= sizeof(message)) {
                    ptn_abort_out_of_memory();
                }
                ptn_throw_exception(runtime, "ValueError", message);
                return 0;
            }
            end = string_len - (size_t)trim;
            if (end < start) {
                end = start;
            }
        }
    }

    *start_out = start;
    *end_out = end;
    return 1;
}

static PtnValue ptn_internal_substr_compare(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, "substr_compare", 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, "substr_compare", 2, "needle", args[1], line);
    int64_t raw_offset = ptn_internal_expect_integer_arg(runtime, "substr_compare", 3, "offset", args[2], line);
    int has_length = argc >= 4 && ptn_value_deref(args[3]).type != PTN_NULL;
    int64_t raw_length = has_length
        ? ptn_internal_expect_integer_arg(runtime, "substr_compare", 4, "length", args[3], line)
        : 0;
    if (has_length && raw_length < 0) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "substr_compare(): Argument #4 ($length) must be greater than or equal to 0"
        );
        return ptn_null();
    }
    if (raw_offset >= 0 && (uint64_t)raw_offset > (uint64_t)haystack.len) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "substr_compare(): Argument #3 ($offset) must be contained in argument #1 ($haystack)"
        );
        return ptn_null();
    }

    size_t start = 0;
    size_t end = haystack.len;
    if (!ptn_string_window_from_offset_length(
            runtime,
            "substr_compare",
            3,
            "offset",
            4,
            "length",
            haystack.len,
            raw_offset,
            has_length,
            raw_length,
            &start,
            &end
        )) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        return ptn_null();
    }

    int case_insensitive = argc >= 5 && ptn_is_truthy(args[4]);
    size_t window_len = end - start;
    int compared;
    if (has_length) {
        size_t limit = (size_t)raw_length;
        compared = case_insensitive
            ? ptn_compare_string_prefix_bytes_ascii_case_insensitive_php_result(
                (const unsigned char *)haystack.data + start,
                window_len,
                (const unsigned char *)needle.data,
                needle.len,
                limit
            )
            : ptn_compare_string_prefix_bytes_php_result(
                (const unsigned char *)haystack.data + start,
                window_len,
                (const unsigned char *)needle.data,
                needle.len,
                limit
            );
    } else {
        compared = case_insensitive
            ? ptn_compare_string_bytes_ascii_case_insensitive_php_result(
                (const unsigned char *)haystack.data + start,
                window_len,
                (const unsigned char *)needle.data,
                needle.len
            )
            : ptn_compare_string_bytes_php_result(
                (const unsigned char *)haystack.data + start,
                window_len,
                (const unsigned char *)needle.data,
                needle.len
            );
    }
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return ptn_int(compared);
}

static size_t ptn_similar_text_score(
    const unsigned char *left,
    size_t left_len,
    const unsigned char *right,
    size_t right_len
) {
    size_t best_len = 0;
    size_t best_left = 0;
    size_t best_right = 0;
    for (size_t i = 0; i < left_len; i++) {
        for (size_t j = 0; j < right_len; j++) {
            size_t run = 0;
            while (i + run < left_len && j + run < right_len && left[i + run] == right[j + run]) {
                run++;
            }
            if (run > best_len) {
                best_len = run;
                best_left = i;
                best_right = j;
            }
        }
    }
    if (best_len == 0) {
        return 0;
    }

    size_t score = best_len;
    if (best_left != 0 && best_right != 0) {
        score += ptn_similar_text_score(left, best_left, right, best_right);
    }
    size_t left_after = best_left + best_len;
    size_t right_after = best_right + best_len;
    if (left_after < left_len && right_after < right_len) {
        score += ptn_similar_text_score(
            left + left_after,
            left_len - left_after,
            right + right_after,
            right_len - right_after
        );
    }
    return score;
}

static PtnValue ptn_internal_similar_text(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand left =
        ptn_internal_expect_string_arg(runtime, "similar_text", 1, "string1", args[0], line);
    PtnStringOperand right =
        ptn_internal_expect_string_arg(runtime, "similar_text", 2, "string2", args[1], line);
    size_t score = ptn_similar_text_score(
        (const unsigned char *)left.data,
        left.len,
        (const unsigned char *)right.data,
        right.len
    );
    if (argc >= 3 && args[2].type == PTN_REFERENCE) {
        double percent = (left.len + right.len) == 0
            ? 0.0
            : ((double)score * 200.0) / (double)(left.len + right.len);
        ptn_reference_assign(runtime, args[2].as.reference, ptn_float(percent));
    }
    ptn_string_operand_free(left);
    ptn_string_operand_free(right);
    if (score > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)score);
}

static int ptn_strtok_is_delimiter(unsigned char byte, const unsigned char *tokens, size_t token_len) {
    for (size_t i = 0; i < token_len; i++) {
        if (tokens[i] == byte) {
            return 1;
        }
    }
    return 0;
}

static PtnRuntime *ptn_strtok_state_runtime(PtnRuntime *runtime) {
    return runtime->lifecycle_root == NULL ? runtime : runtime->lifecycle_root;
}

static void ptn_strtok_replace_state(PtnRuntime *runtime, PtnStringOperand string) {
    PtnRuntime *state_runtime = ptn_strtok_state_runtime(runtime);
    free(state_runtime->strtok_string);
    state_runtime->strtok_string = ptn_duplicate_string_len(string.data, string.len);
    state_runtime->strtok_len = string.len;
    state_runtime->strtok_offset = 0;
    state_runtime->strtok_has_state = 1;
}

static PtnValue ptn_internal_strtok(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnRuntime *state_runtime = ptn_strtok_state_runtime(runtime);
    PtnStringOperand tokens;
    int starting = argc >= 2;
    if (starting) {
        PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "strtok", 1, "string", args[0], line);
        tokens = ptn_internal_expect_string_arg(runtime, "strtok", 2, "token", args[1], line);
        ptn_strtok_replace_state(runtime, string);
        ptn_string_operand_free(string);
    } else {
        if (!state_runtime->strtok_has_state) {
            ptn_emit_spaced_warning(
                &runtime->diagnostics,
                "strtok(): Both arguments must be provided when starting tokenization",
                line
            );
            return ptn_bool(0);
        }
        tokens = ptn_internal_expect_string_arg(runtime, "strtok", 1, "token", args[0], line);
    }

    if (tokens.len == 0) {
        ptn_string_operand_free(tokens);
        return ptn_bool(0);
    }

    size_t cursor = state_runtime->strtok_offset;
    size_t original_cursor = cursor;
    while (cursor < state_runtime->strtok_len &&
           ptn_strtok_is_delimiter(
               (unsigned char)state_runtime->strtok_string[cursor],
               (const unsigned char *)tokens.data,
               tokens.len
           )) {
        cursor++;
    }

    if (cursor >= state_runtime->strtok_len) {
        if ((starting && state_runtime->strtok_len != 0) || (!starting && original_cursor < state_runtime->strtok_len)) {
            state_runtime->strtok_has_state = 0;
        }
        state_runtime->strtok_offset = state_runtime->strtok_len;
        ptn_string_operand_free(tokens);
        return ptn_bool(0);
    }

    size_t start = cursor;
    while (cursor < state_runtime->strtok_len &&
           !ptn_strtok_is_delimiter(
               (unsigned char)state_runtime->strtok_string[cursor],
               (const unsigned char *)tokens.data,
               tokens.len
           )) {
        cursor++;
    }
    state_runtime->strtok_offset = cursor < state_runtime->strtok_len ? cursor + 1 : cursor;
    char *token = ptn_duplicate_string_len(state_runtime->strtok_string + start, cursor - start);
    ptn_string_operand_free(tokens);
    return ptn_owned_string_len(token, cursor - start);
}

static PtnValue ptn_internal_str_contains(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, "str_contains", 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, "str_contains", 2, "needle", args[1], line);
    int contains = needle.len == 0;
    if (!contains && needle.len <= haystack.len) {
        for (size_t offset = 0; offset <= haystack.len - needle.len; offset++) {
            if (memcmp(haystack.data + offset, needle.data, needle.len) == 0) {
                contains = 1;
                break;
            }
        }
    }
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return ptn_bool(contains);
}

static PtnValue ptn_internal_str_starts_with(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, "str_starts_with", 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, "str_starts_with", 2, "needle", args[1], line);
    size_t haystack_len = haystack.len;
    size_t needle_len = needle.len;
    int starts = needle_len <= haystack_len && memcmp(haystack.data, needle.data, needle_len) == 0;
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return ptn_bool(starts);
}

static PtnValue ptn_internal_str_ends_with(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, "str_ends_with", 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, "str_ends_with", 2, "needle", args[1], line);
    size_t haystack_len = haystack.len;
    size_t needle_len = needle.len;
    int ends =
        needle_len <= haystack_len &&
        memcmp(haystack.data + haystack_len - needle_len, needle.data, needle_len) == 0;
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return ptn_bool(ends);
}

static PtnValue ptn_internal_strpbrk(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "strpbrk", 1, "string", args[0], line);
    PtnStringOperand characters = ptn_internal_expect_string_arg(runtime, "strpbrk", 2, "characters", args[1], line);

    if (characters.len == 0) {
        ptn_string_operand_free(string);
        ptn_string_operand_free(characters);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "strpbrk(): Argument #2 ($characters) must be a non-empty string"
        );
        return ptn_null();
    }

    unsigned char byte_set[256] = {0};
    for (size_t i = 0; i < characters.len; i++) {
        byte_set[(unsigned char)characters.data[i]] = 1;
    }

    for (size_t i = 0; i < string.len; i++) {
        if (byte_set[(unsigned char)string.data[i]]) {
            size_t result_len = string.len - i;
            char *result = ptn_duplicate_string_len(string.data + i, result_len);
            ptn_string_operand_free(string);
            ptn_string_operand_free(characters);
            return ptn_owned_string_len(result, result_len);
        }
    }

    ptn_string_operand_free(string);
    ptn_string_operand_free(characters);
    return ptn_bool(0);
}

static int ptn_match_bytes_at(
    const char *haystack,
    const char *needle,
    size_t needle_len,
    int case_insensitive
) {
    for (size_t i = 0; i < needle_len; i++) {
        unsigned char haystack_byte = (unsigned char)haystack[i];
        unsigned char needle_byte = (unsigned char)needle[i];
        if (case_insensitive) {
            haystack_byte = ptn_ascii_lower_byte(haystack_byte);
            needle_byte = ptn_ascii_lower_byte(needle_byte);
        }
        if (haystack_byte != needle_byte) {
            return 0;
        }
    }
    return 1;
}

static size_t ptn_find_bytes_from(
    const char *haystack,
    size_t haystack_len,
    const char *needle,
    size_t needle_len,
    size_t start,
    int case_insensitive
) {
    if (start > haystack_len) {
        return SIZE_MAX;
    }
    if (needle_len == 0) {
        return start;
    }
    if (needle_len > haystack_len - start) {
        return SIZE_MAX;
    }
    size_t last = haystack_len - needle_len;
    for (size_t offset = start; offset <= last; offset++) {
        if (ptn_match_bytes_at(haystack + offset, needle, needle_len, case_insensitive)) {
            return offset;
        }
    }
    return SIZE_MAX;
}

static size_t ptn_rfind_bytes_between(
    const char *haystack,
    size_t haystack_len,
    const char *needle,
    size_t needle_len,
    size_t start,
    size_t max_start,
    int case_insensitive
) {
    if (needle_len == 0) {
        return max_start <= haystack_len ? max_start : haystack_len;
    }
    if (start > haystack_len || needle_len > haystack_len) {
        return SIZE_MAX;
    }
    size_t last = haystack_len - needle_len;
    if (max_start > last) {
        max_start = last;
    }
    if (start > max_start) {
        return SIZE_MAX;
    }
    size_t cursor = max_start + 1;
    while (cursor > start) {
        size_t offset = cursor - 1;
        if (ptn_match_bytes_at(haystack + offset, needle, needle_len, case_insensitive)) {
            return offset;
        }
        cursor--;
    }
    return SIZE_MAX;
}

static int ptn_normalize_string_offset(
    PtnRuntime *runtime,
    const char *function_name,
    int64_t raw_offset,
    size_t string_len,
    size_t *offset_out
) {
    if (raw_offset < 0) {
        uint64_t offset_magnitude = raw_offset == INT64_MIN
            ? ((uint64_t)INT64_MAX + 1)
            : (uint64_t)(-raw_offset);
        if (offset_magnitude > (uint64_t)string_len) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Argument #3 ($offset) must be contained in argument #1 ($haystack)",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return 0;
        }
        *offset_out = string_len - (size_t)offset_magnitude;
        return 1;
    }
    if ((uint64_t)raw_offset > (uint64_t)string_len) {
        char message[128];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #3 ($offset) must be contained in argument #1 ($haystack)",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    *offset_out = (size_t)raw_offset;
    return 1;
}

static PtnValue ptn_string_position_value(size_t offset) {
    if (offset > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)offset);
}

static PtnValue ptn_internal_strpos_named(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int case_insensitive
) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, function_name, 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, function_name, 2, "needle", args[1], line);
    int64_t raw_offset = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, function_name, 3, "offset", args[2], line)
        : 0;
    size_t offset = 0;
    if (!ptn_normalize_string_offset(runtime, function_name, raw_offset, haystack.len, &offset)) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        return ptn_null();
    }

    size_t match = ptn_find_bytes_from(
        haystack.data,
        haystack.len,
        needle.data,
        needle.len,
        offset,
        case_insensitive
    );
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return match == SIZE_MAX ? ptn_bool(0) : ptn_string_position_value(match);
}

static PtnValue ptn_internal_strpos(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strpos_named(runtime, "strpos", argc, args, line, 0);
}

static PtnValue ptn_internal_stripos(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strpos_named(runtime, "stripos", argc, args, line, 1);
}

static PtnValue ptn_internal_strrpos_named(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int case_insensitive
) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, function_name, 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, function_name, 2, "needle", args[1], line);
    int64_t raw_offset = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, function_name, 3, "offset", args[2], line)
        : 0;
    size_t offset = 0;
    if (!ptn_normalize_string_offset(runtime, function_name, raw_offset, haystack.len, &offset)) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        return ptn_null();
    }

    size_t start = 0;
    size_t max_start = haystack.len;
    if (raw_offset >= 0) {
        start = offset;
    } else {
        max_start = offset;
    }

    size_t match = ptn_rfind_bytes_between(
        haystack.data,
        haystack.len,
        needle.data,
        needle.len,
        start,
        max_start,
        case_insensitive
    );
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return match == SIZE_MAX ? ptn_bool(0) : ptn_string_position_value(match);
}

static PtnValue ptn_internal_strrpos(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strrpos_named(runtime, "strrpos", argc, args, line, 0);
}

static PtnValue ptn_internal_strripos(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strrpos_named(runtime, "strripos", argc, args, line, 1);
}

static PtnValue ptn_internal_strstr_named(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int case_insensitive
) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, function_name, 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, function_name, 2, "needle", args[1], line);
    int before_needle = argc >= 3 && ptn_is_truthy(args[2]);
    size_t match = ptn_find_bytes_from(
        haystack.data,
        haystack.len,
        needle.data,
        needle.len,
        0,
        case_insensitive
    );
    ptn_string_operand_free(needle);
    if (match == SIZE_MAX) {
        ptn_string_operand_free(haystack);
        return ptn_bool(0);
    }

    size_t start = before_needle ? 0 : match;
    size_t len = before_needle ? match : haystack.len - match;
    PtnValue result = ptn_owned_string_len(ptn_duplicate_string_len(haystack.data + start, len), len);
    ptn_string_operand_free(haystack);
    return result;
}

static PtnValue ptn_internal_strstr(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strstr_named(runtime, "strstr", argc, args, line, 0);
}

