static const char *ptn_runtime_current_include_path(PtnRuntime *runtime);
static void ptn_emit_function_warning(
    PtnRuntime *runtime,
    const char *function_name,
    const char *detail,
    size_t line
);

static int ptn_ascii_case_has_prefix(const char *value, const char *prefix) {
    size_t prefix_len = strlen(prefix);
    return strlen(value) >= prefix_len && ptn_ascii_case_equal_n(value, prefix, prefix_len);
}

static int ptn_parse_php_temp_max_memory(const char *path, size_t *max_memory) {
    *max_memory = 2 * 1024 * 1024;
    const char *prefix = "php://temp";
    size_t prefix_len = strlen(prefix);
    if (!ptn_ascii_case_has_prefix(path, prefix)) {
        return 0;
    }
    const char *suffix = path + prefix_len;
    if (suffix[0] == '\0') {
        return 1;
    }
    if (suffix[0] != '/') {
        return 0;
    }
    const char *setting = suffix + 1;
    const char *colon_prefix = "maxmemory:";
    const char *equals_prefix = "maxmemory=";
    if (ptn_ascii_case_has_prefix(setting, colon_prefix)) {
        setting += strlen(colon_prefix);
    } else if (ptn_ascii_case_has_prefix(setting, equals_prefix)) {
        setting += strlen(equals_prefix);
    } else {
        return 0;
    }
    if (setting[0] == '\0') {
        return 0;
    }
    size_t parsed = 0;
    for (const char *cursor = setting; *cursor != '\0'; cursor++) {
        unsigned char byte = (unsigned char)*cursor;
        if (byte < '0' || byte > '9') {
            return 0;
        }
        size_t digit = (size_t)(byte - '0');
        if (parsed > (SIZE_MAX - digit) / 10) {
            parsed = SIZE_MAX;
        } else {
            parsed = parsed * 10 + digit;
        }
    }
    *max_memory = parsed;
    return 1;
}

static const char *ptn_php_memory_stream_mode(const char *mode, int *writable, int *append) {
    *append = mode[0] == 'a' || mode[0] == 'A';
    if ((mode[0] == 'r' || mode[0] == 'R') && strchr(mode, '+') == NULL) {
        *writable = 0;
        return "rb";
    }
    *writable = 1;
    return *append ? "a+b" : "w+b";
}

static int ptn_try_open_php_memory_stream(const char *path, const char *mode, PtnValue *out) {
    int writable = 0;
    int append = 0;
    const char *stream_mode = ptn_php_memory_stream_mode(mode, &writable, &append);
    if (ptn_ascii_case_equal(path, "php://memory")) {
        *out = ptn_resource(ptn_resource_new_memory_stream(
            path,
            stream_mode,
            PTN_STREAM_BACKEND_MEMORY,
            SIZE_MAX,
            writable,
            append
        ));
        return 1;
    }

    size_t max_memory = 0;
    if (!ptn_parse_php_temp_max_memory(path, &max_memory)) {
        return 0;
    }
    *out = ptn_resource(ptn_resource_new_memory_stream(
        path,
        stream_mode,
        PTN_STREAM_BACKEND_TEMP,
        max_memory,
        writable,
        append
    ));
    return 1;
}

static char *ptn_fopen_c_mode(const char *mode) {
    if (mode[0] != 'x') {
        return ptn_duplicate_string(mode);
    }
    size_t len = strlen(mode);
    char *c_mode = malloc(len + 2);
    if (c_mode == NULL) {
        ptn_abort_out_of_memory();
    }
    c_mode[0] = 'w';
    if (len > 1) {
        memcpy(c_mode + 1, mode + 1, len - 1);
    }
    c_mode[len] = 'x';
    c_mode[len + 1] = '\0';
    return c_mode;
}

static int ptn_stream_mode_is_append(PtnResource *resource) {
    return resource != NULL && resource->stream_mode != NULL && resource->stream_mode[0] == 'a';
}

static PtnValue ptn_internal_fopen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "fopen", 1, "filename", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "fopen(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    PtnStringOperand mode_operand = ptn_internal_expect_string_arg(runtime, "fopen", 2, "mode", args[1], line);
    char *mode = ptn_path_operand_to_c_string(mode_operand);
    ptn_string_operand_free(mode_operand);
    if (mode == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "fopen(): Argument #2 ($mode) must not contain any null bytes", line);
        free(path);
        return ptn_bool(0);
    }

    PtnValue php_stream;
    if (ptn_try_open_php_memory_stream(path, mode, &php_stream)) {
        free(mode);
        free(path);
        return php_stream;
    }

    char *c_mode = ptn_fopen_c_mode(mode);
    FILE *stream = fopen(path, c_mode);
    free(c_mode);
    if (stream == NULL) {
        char detail[192];
        int needed = snprintf(detail, sizeof(detail), "Failed to open stream: %s", strerror(errno));
        if (needed < 0 || (size_t)needed >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_file_warning(runtime, "fopen", path, detail, line);
        free(mode);
        free(path);
        return ptn_bool(0);
    }
    if (mode[0] == 'a') {
        (void)fseek(stream, 0, SEEK_SET);
    }

    PtnValue resource = ptn_resource(ptn_resource_new_stream(stream, path, mode));
    free(mode);
    free(path);
    return resource;
}

static PtnValue ptn_internal_opendir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "opendir", 1, "directory", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "opendir(): Filename contains null byte", line);
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_emit_file_warning(runtime, "opendir", path, "directory streams are unsupported on this platform", line);
    free(path);
    return ptn_bool(0);
#else
    DIR *directory = opendir(path);
    if (directory == NULL) {
        ptn_emit_file_warning(runtime, "opendir", path, strerror(errno), line);
        free(path);
        return ptn_bool(0);
    }

    PtnValue resource = ptn_resource(ptn_resource_new_directory(directory, path));
    free(path);
    return resource;
#endif
}

static PtnValue ptn_internal_closedir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnValue value = ptn_value_deref(args[0]);
    if (value.type == PTN_NULL) {
        ptn_throw_exception(runtime, "TypeError", "No resource supplied");
        return ptn_null();
    }
    if (value.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "closedir(): Argument #1 ($dir_handle) must be of type resource or null, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (value.as.resource->directory == NULL) {
        ptn_throw_exception(
            runtime,
            "TypeError",
            "closedir(): Argument #1 ($dir_handle) must be a valid Directory resource"
        );
        return ptn_null();
    }
    ptn_resource_close(value.as.resource);
    return ptn_null();
}

static PtnValue ptn_internal_fclose(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnValue value = ptn_value_deref(args[0]);
    if (value.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "fclose(): Argument #1 ($stream) must be of type resource, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (!ptn_stream_resource_is_open(value.as.resource)) {
        return ptn_bool(0);
    }
    ptn_resource_close(value.as.resource);
    (void)line;
    return ptn_bool(1);
}

