static int ptn_scandir_name_compare(const void *left, const void *right) {
    const char *left_name = *(const char * const *)left;
    const char *right_name = *(const char * const *)right;
    return strcmp(left_name, right_name);
}

static PtnValue ptn_internal_scandir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_value_to_string_operand(args[0]);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "scandir(): Filename contains null byte", line);
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_emit_file_warning(runtime, "scandir", path, "directory scanning is unsupported on this platform", line);
    free(path);
    return ptn_bool(0);
#else
    DIR *dir = opendir(path);
    if (dir == NULL) {
        ptn_emit_file_warning(runtime, "scandir", path, strerror(errno), line);
        free(path);
        return ptn_bool(0);
    }

    char **names = NULL;
    size_t len = 0;
    size_t capacity = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (len == capacity) {
            size_t new_capacity = capacity == 0 ? 16 : capacity * 2;
            if (new_capacity < capacity) {
                closedir(dir);
                free(path);
                ptn_abort_out_of_memory();
            }
            char **new_names = realloc(names, new_capacity * sizeof(char *));
            if (new_names == NULL) {
                closedir(dir);
                free(path);
                ptn_abort_out_of_memory();
            }
            names = new_names;
            capacity = new_capacity;
        }
        names[len++] = ptn_duplicate_string(entry->d_name);
    }
    closedir(dir);
    free(path);
    qsort(names, len, sizeof(char *), ptn_scandir_name_compare);

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < len; i++) {
        if (i > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(result.as.array, ptn_array_int_key((int64_t)i), ptn_owned_string(names[i]));
    }
    free(names);
    return result;
#endif
}

static int ptn_fnmatch_flags(int64_t flags) {
    int c_flags = 0;
#if defined(FNM_NOESCAPE)
    if ((flags & PTN_FNM_NOESCAPE) != 0) {
        c_flags |= FNM_NOESCAPE;
    }
#endif
#if defined(FNM_PATHNAME)
    if ((flags & PTN_FNM_PATHNAME) != 0) {
        c_flags |= FNM_PATHNAME;
    }
#endif
#if defined(FNM_PERIOD)
    if ((flags & PTN_FNM_PERIOD) != 0) {
        c_flags |= FNM_PERIOD;
    }
#endif
#if defined(FNM_CASEFOLD)
    if ((flags & PTN_FNM_CASEFOLD) != 0) {
        c_flags |= FNM_CASEFOLD;
    }
#endif
    return c_flags;
}

static PtnValue ptn_internal_fnmatch(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_internal_expect_string_arg(runtime, "fnmatch", 1, "pattern", args[0], line);
    PtnStringOperand filename = ptn_internal_expect_string_arg(runtime, "fnmatch", 2, "filename", args[1], line);
    int64_t flags = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "fnmatch", 3, "flags", args[2], line)
        : 0;
    char *pattern_c = ptn_path_operand_to_c_string(pattern);
    char *filename_c = ptn_path_operand_to_c_string(filename);
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(filename);
    if (pattern_c == NULL || filename_c == NULL) {
        free(pattern_c);
        free(filename_c);
        ptn_throw_exception(runtime, "ValueError", "fnmatch(): Arguments must not contain any null bytes");
        return ptn_null();
    }
#if defined(_WIN32)
    int matched = strcmp(pattern_c, filename_c) == 0;
#else
    int matched = fnmatch(pattern_c, filename_c, ptn_fnmatch_flags(flags)) == 0;
#endif
    free(pattern_c);
    free(filename_c);
    return ptn_bool(matched);
}

static int ptn_glob_flags(int64_t flags) {
    int c_flags = 0;
#if defined(GLOB_MARK)
    if ((flags & PTN_GLOB_MARK) != 0) {
        c_flags |= GLOB_MARK;
    }
#endif
#if defined(GLOB_NOSORT)
    if ((flags & PTN_GLOB_NOSORT) != 0) {
        c_flags |= GLOB_NOSORT;
    }
#endif
#if defined(GLOB_NOCHECK)
    if ((flags & PTN_GLOB_NOCHECK) != 0) {
        c_flags |= GLOB_NOCHECK;
    }
#endif
#if defined(GLOB_NOESCAPE)
    if ((flags & PTN_GLOB_NOESCAPE) != 0) {
        c_flags |= GLOB_NOESCAPE;
    }
#endif
#if defined(GLOB_BRACE)
    if ((flags & PTN_GLOB_BRACE) != 0) {
        c_flags |= GLOB_BRACE;
    }
#endif
#if defined(GLOB_ONLYDIR)
    if ((flags & PTN_GLOB_ONLYDIR) != 0) {
        c_flags |= GLOB_ONLYDIR;
    }
#endif
#if defined(GLOB_ERR)
    if ((flags & PTN_GLOB_ERR) != 0) {
        c_flags |= GLOB_ERR;
    }
#endif
    return c_flags;
}

static PtnValue ptn_internal_glob(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    char *pattern = ptn_internal_path_arg_c_string_or_value_error(runtime, "glob", 1, "pattern", args[0], line);
    if (pattern == NULL) {
        return ptn_null();
    }
    int64_t flags = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "glob", 2, "flags", args[1], line)
        : 0;
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
#if defined(_WIN32)
    (void)flags;
    free(pattern);
    return result;
#else
    glob_t matches;
    memset(&matches, 0, sizeof(matches));
    int status = glob(pattern, ptn_glob_flags(flags), NULL, &matches);
    free(pattern);
    if (status != 0 && status != GLOB_NOMATCH) {
        globfree(&matches);
        return ptn_bool(0);
    }
    for (size_t i = 0; i < matches.gl_pathc; i++) {
        if (i > (size_t)INT64_MAX) {
            globfree(&matches);
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(
            result.as.array,
            ptn_array_int_key((int64_t)i),
            ptn_owned_string(ptn_duplicate_string(matches.gl_pathv[i]))
        );
    }
    globfree(&matches);
    return result;
#endif
}

static PtnValue ptn_internal_disk_space(PtnRuntime *runtime, const char *function_name, PtnValue value, int total, size_t line) {
    char *path = ptn_internal_path_arg_c_string_or_value_error(runtime, function_name, 1, "directory", value, line);
    if (path == NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    free(path);
    return ptn_bool(0);
#else
    struct statvfs info;
    if (statvfs(path, &info) != 0) {
        ptn_emit_file_warning(runtime, function_name, path, strerror(errno), line);
        free(path);
        return ptn_bool(0);
    }
    free(path);
    unsigned long blocks = total ? info.f_blocks : info.f_bavail;
    return ptn_float((double)blocks * (double)info.f_frsize);
#endif
}

static PtnValue ptn_internal_disk_free_space(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    return ptn_internal_disk_space(runtime, "disk_free_space", args[0], 0, line);
}

static PtnValue ptn_internal_diskfreespace(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    return ptn_internal_disk_space(runtime, "diskfreespace", args[0], 0, line);
}

static PtnValue ptn_internal_disk_total_space(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    return ptn_internal_disk_space(runtime, "disk_total_space", args[0], 1, line);
}

static PtnValue ptn_internal_link(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    char *target = ptn_internal_path_arg_c_string_or_value_error(runtime, "link", 1, "target", args[0], line);
    if (target == NULL) {
        return ptn_null();
    }
    char *link_name = ptn_internal_path_arg_c_string_or_value_error(runtime, "link", 2, "link", args[1], line);
    if (link_name == NULL) {
        free(target);
        return ptn_null();
    }
#if defined(_WIN32)
    int ok = 0;
#else
    int ok = link(target, link_name) == 0;
#endif
    if (!ok) {
        ptn_emit_function_warning(runtime, "link", strerror(errno), line);
    }
    free(link_name);
    free(target);
    return ptn_bool(ok);
}

static PtnValue ptn_internal_symlink(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    char *target = ptn_internal_path_arg_c_string_or_value_error(runtime, "symlink", 1, "target", args[0], line);
    if (target == NULL) {
        return ptn_null();
    }
    char *link_name = ptn_internal_path_arg_c_string_or_value_error(runtime, "symlink", 2, "link", args[1], line);
    if (link_name == NULL) {
        free(target);
        return ptn_null();
    }
#if defined(_WIN32)
    int ok = 0;
#else
    int ok = symlink(target, link_name) == 0;
#endif
    if (!ok) {
        ptn_emit_function_warning(runtime, "symlink", strerror(errno), line);
    }
    free(link_name);
    free(target);
    return ptn_bool(ok);
}

static PtnValue ptn_internal_linkinfo(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    char *path = ptn_internal_path_arg_c_string_or_value_error(runtime, "linkinfo", 1, "path", args[0], line);
    if (path == NULL) {
        return ptn_null();
    }
    struct stat info;
    if (ptn_lstat_path(path, &info) != 0) {
        ptn_emit_function_warning(runtime, "linkinfo", strerror(errno), line);
        free(path);
        return ptn_int(-1);
    }
    free(path);
    return ptn_int(info.st_dev > 0 ? (int64_t)info.st_dev : 1);
}

static PtnValue ptn_internal_readlink(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    char *path = ptn_internal_path_arg_c_string_or_value_error(runtime, "readlink", 1, "path", args[0], line);
    if (path == NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    ptn_emit_function_warning(runtime, "readlink", "Invalid argument", line);
    free(path);
    return ptn_bool(0);
#else
    size_t capacity = 256;
    char *buffer = NULL;
    for (;;) {
        char *next = realloc(buffer, capacity + 1);
        if (next == NULL) {
            free(buffer);
            free(path);
            ptn_abort_out_of_memory();
        }
        buffer = next;
        ssize_t len = readlink(path, buffer, capacity);
        if (len < 0) {
            ptn_emit_function_warning(runtime, "readlink", strerror(errno), line);
            free(buffer);
            free(path);
            return ptn_bool(0);
        }
        if ((size_t)len < capacity) {
            buffer[len] = '\0';
            free(path);
            return ptn_owned_string_len(buffer, (size_t)len);
        }
        if (capacity > SIZE_MAX / 2) {
            free(buffer);
            free(path);
            ptn_abort_out_of_memory();
        }
        capacity *= 2;
    }
#endif
}

static PtnValue ptn_internal_umask(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
#if defined(_WIN32)
    (void)args;
    return ptn_int(0);
#else
    mode_t old_mask;
    if (argc == 0) {
        old_mask = umask(0);
        umask(old_mask);
    } else {
        old_mask = umask((mode_t)ptn_value_to_integer(args[0]));
    }
    return ptn_int((int64_t)old_mask);
#endif
}

static PtnValue ptn_internal_mkdir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand path_operand = ptn_value_to_string_operand(args[0]);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "mkdir(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    int64_t mode = ptn_mkdir_mode_from_args(argc, args);
    int recursive = argc >= 3 && ptn_is_truthy(args[2]);
    int created = recursive ? ptn_mkdir_recursive(path, mode) : ptn_platform_mkdir(path, mode) == 0;
    if (created) {
        free(path);
        return ptn_bool(1);
    }

    ptn_emit_file_warning(runtime, "mkdir", path, strerror(errno), line);
    free(path);
    return ptn_bool(0);
}

static PtnValue ptn_internal_rmdir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_value_to_string_operand(args[0]);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "rmdir(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    if (rmdir(path) == 0) {
        free(path);
        return ptn_bool(1);
    }

    ptn_emit_file_warning(runtime, "rmdir", path, strerror(errno), line);
    free(path);
    return ptn_bool(0);
}

static size_t ptn_substr_clamped_positive(int64_t value, size_t limit) {
    if (value <= 0) {
        return 0;
    }
    uint64_t unsigned_value = (uint64_t)value;
    if (unsigned_value > (uint64_t)limit) {
        return limit;
    }
    return (size_t)unsigned_value;
}

static size_t ptn_substr_clamped_negative_distance(int64_t value, size_t limit) {
    if (value >= 0) {
        return 0;
    }
    if (value == INT64_MIN) {
        return limit;
    }
    uint64_t distance = (uint64_t)(-value);
    if (distance > (uint64_t)limit) {
        return limit;
    }
    return (size_t)distance;
}

static size_t ptn_substr_start_offset(size_t string_len, int64_t start) {
    if (start >= 0) {
        return ptn_substr_clamped_positive(start, string_len);
    }
    size_t distance = ptn_substr_clamped_negative_distance(start, string_len);
    return string_len - distance;
}

static char *ptn_substr_copy(const char *string, size_t start, size_t len) {
    if (len == SIZE_MAX) {
        ptn_abort_out_of_memory();
    }
    char *result = malloc(len + 1);
    if (result == NULL) {
        ptn_abort_out_of_memory();
    }
    memcpy(result, string + start, len);
    result[len] = '\0';
    return result;
}

static size_t ptn_string_span_slice_end(size_t string_len, size_t start, int has_length, int64_t length) {
    if (!has_length) {
        return string_len;
    }
    if (length >= 0) {
        size_t requested_len = ptn_substr_clamped_positive(length, string_len);
        size_t available_len = string_len - start;
        if (requested_len > available_len) {
            requested_len = available_len;
        }
        return start + requested_len;
    }
    size_t truncate_len = ptn_substr_clamped_negative_distance(length, string_len);
    size_t end = string_len - truncate_len;
    return end < start ? start : end;
}

static PtnValue ptn_internal_string_span(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int accept_mask_bytes
) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, function_name, 1, "string", args[0], line);
    PtnStringOperand mask = ptn_internal_expect_string_arg(runtime, function_name, 2, "characters", args[1], line);
    int64_t start_value = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, function_name, 3, "offset", args[2], line)
        : 0;
    int has_length = argc >= 4 && ptn_value_deref(args[3]).type != PTN_NULL;
    int64_t length_value = has_length
        ? ptn_internal_expect_integer_arg(runtime, function_name, 4, "length", args[3], line)
        : 0;

    unsigned char table[256];
    memset(table, 0, sizeof(table));
    for (size_t i = 0; i < mask.len; i++) {
        table[(unsigned char)mask.data[i]] = 1;
    }

    size_t start = ptn_substr_start_offset(string.len, start_value);
    size_t end = ptn_string_span_slice_end(string.len, start, has_length, length_value);
    size_t count = 0;
    for (size_t i = start; i < end; i++) {
        int in_mask = table[(unsigned char)string.data[i]] != 0;
        if ((accept_mask_bytes && !in_mask) || (!accept_mask_bytes && in_mask)) {
            break;
        }
        count++;
    }

    ptn_string_operand_free(string);
    ptn_string_operand_free(mask);
    return ptn_int((int64_t)count);
}

static PtnValue ptn_internal_strspn(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_string_span(runtime, "strspn", argc, args, line, 1);
}

static PtnValue ptn_internal_strcspn(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_string_span(runtime, "strcspn", argc, args, line, 0);
}

static PtnValue ptn_internal_substr(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "substr", 1, "string", args[0], line);
    size_t string_len = string.len;
    size_t start = ptn_substr_start_offset(string_len, ptn_value_to_integer(args[1]));
    size_t end = string_len;

    if (argc >= 3 && args[2].type != PTN_NULL) {
        int64_t length = ptn_value_to_integer(args[2]);
        if (length >= 0) {
            size_t requested_len = ptn_substr_clamped_positive(length, string_len);
            size_t available_len = string_len - start;
            if (requested_len > available_len) {
                requested_len = available_len;
            }
            end = start + requested_len;
        } else {
            size_t truncate_len = ptn_substr_clamped_negative_distance(length, string_len);
            end = string_len - truncate_len;
            if (end < start) {
                end = start;
            }
        }
    }

    char *substring = ptn_substr_copy(string.data, start, end - start);
    size_t substring_len = end - start;
    ptn_string_operand_free(string);
    return ptn_owned_string_len(substring, substring_len);
}

static int ptn_is_path_separator(char byte) {
#ifdef _WIN32
    return byte == '/' || byte == '\\';
#else
    return byte == '/';
#endif
}

static char *ptn_dirname_string(const char *path, size_t len, size_t *dirname_len) {
    if (len == 0) {
        *dirname_len = 0;
        return ptn_duplicate_string("");
    }
    while (len > 1 && ptn_is_path_separator(path[len - 1])) {
        len--;
    }

    size_t end = len;
    while (end > 0 && !ptn_is_path_separator(path[end - 1])) {
        end--;
    }
    if (end == 0) {
        *dirname_len = 1;
        return ptn_duplicate_string(".");
    }
    while (end > 1 && ptn_is_path_separator(path[end - 1])) {
        end--;
    }

    char *dirname = malloc(end + 1);
    if (dirname == NULL) {
        ptn_abort_out_of_memory();
    }
    memcpy(dirname, path, end);
    dirname[end] = '\0';
    *dirname_len = end;
    return dirname;
}

static char *ptn_dirname_string_levels(const char *path, size_t len, int64_t levels, size_t *dirname_len) {
    char *current = ptn_duplicate_string_len(path, len);
    size_t current_len = len;

    for (int64_t level = 0; level < levels; level++) {
        size_t next_len = 0;
        char *next = ptn_dirname_string(current, current_len, &next_len);
        if (next_len == current_len && memcmp(next, current, current_len) == 0) {
            free(current);
            *dirname_len = next_len;
            return next;
        }
        free(current);
        current = next;
        current_len = next_len;
    }

    *dirname_len = current_len;
    return current;
}

typedef struct {
    char *dirname;
    size_t dirname_len;
    size_t basename_start;
    size_t basename_len;
    size_t extension_start;
    size_t extension_len;
    size_t filename_len;
    int has_extension;
} PtnPathInfoParts;

static PtnPathInfoParts ptn_pathinfo_parts(PtnStringOperand path) {
    PtnPathInfoParts parts;
    parts.dirname = ptn_dirname_string(path.data, path.len, &parts.dirname_len);

    size_t end = path.len;
    while (end > 0 && ptn_is_path_separator(path.data[end - 1])) {
        end--;
    }

    size_t start = end;
    while (start > 0 && !ptn_is_path_separator(path.data[start - 1])) {
        start--;
    }
    parts.basename_start = start;
    parts.basename_len = end - start;
    parts.has_extension = 0;
    parts.extension_start = start + parts.basename_len;
    parts.extension_len = 0;
    parts.filename_len = parts.basename_len;

    size_t dot = SIZE_MAX;
    for (size_t i = 0; i < parts.basename_len; i++) {
        if (path.data[start + i] == '.') {
            dot = i;
        }
    }
    if (dot != SIZE_MAX) {
        parts.has_extension = 1;
        parts.extension_start = start + dot + 1;
        parts.extension_len = parts.basename_len - dot - 1;
        parts.filename_len = dot;
    }

    return parts;
}

static PtnValue ptn_pathinfo_owned_string(const char *data, size_t len) {
    return ptn_owned_string_len(ptn_duplicate_string_len(data, len), len);
}

static void ptn_pathinfo_array_set_string(PtnValue *result, const char *key, const char *data, size_t len) {
    ptn_array_set_entry(
        result->as.array,
        ptn_array_string_key(key),
        ptn_pathinfo_owned_string(data, len)
    );
}

static PtnValue ptn_internal_pathinfo(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand path = ptn_internal_expect_string_arg(runtime, "pathinfo", 1, "path", args[0], line);
    int64_t flags = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "pathinfo", 2, "flags", args[1], line)
        : PTN_PATHINFO_ALL;

    if (flags < PTN_PATHINFO_DIRNAME || flags > PTN_PATHINFO_ALL) {
        ptn_string_operand_free(path);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "pathinfo(): Argument #2 ($flags) must be one of the PATHINFO_* constants"
        );
        return ptn_null();
    }
    if (
        flags != PTN_PATHINFO_ALL &&
        flags != PTN_PATHINFO_DIRNAME &&
        flags != PTN_PATHINFO_BASENAME &&
        flags != PTN_PATHINFO_EXTENSION &&
        flags != PTN_PATHINFO_FILENAME
    ) {
        ptn_string_operand_free(path);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "pathinfo(): Argument #2 ($flags) must be only one of the PATHINFO_* constants"
        );
        return ptn_null();
    }

    PtnPathInfoParts parts = ptn_pathinfo_parts(path);
    if (flags == PTN_PATHINFO_DIRNAME) {
        PtnValue result = ptn_owned_string_len(parts.dirname, parts.dirname_len);
        ptn_string_operand_free(path);
        return result;
    }
    if (flags == PTN_PATHINFO_BASENAME) {
        PtnValue result = ptn_pathinfo_owned_string(path.data + parts.basename_start, parts.basename_len);
        free(parts.dirname);
        ptn_string_operand_free(path);
        return result;
    }
    if (flags == PTN_PATHINFO_EXTENSION) {
        PtnValue result = ptn_pathinfo_owned_string(path.data + parts.extension_start, parts.extension_len);
        free(parts.dirname);
        ptn_string_operand_free(path);
        return result;
    }
    if (flags == PTN_PATHINFO_FILENAME) {
        PtnValue result = ptn_pathinfo_owned_string(path.data + parts.basename_start, parts.filename_len);
        free(parts.dirname);
        ptn_string_operand_free(path);
        return result;
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    if (parts.dirname_len > 0) {
        ptn_pathinfo_array_set_string(&result, "dirname", parts.dirname, parts.dirname_len);
    }
    ptn_pathinfo_array_set_string(
        &result,
        "basename",
        path.data + parts.basename_start,
        parts.basename_len
    );
    if (parts.has_extension) {
        ptn_pathinfo_array_set_string(
            &result,
            "extension",
            path.data + parts.extension_start,
            parts.extension_len
        );
    }
    ptn_pathinfo_array_set_string(
        &result,
        "filename",
        path.data + parts.basename_start,
        parts.filename_len
    );

    free(parts.dirname);
    ptn_string_operand_free(path);
    return result;
}

static const char *ptn_internal_string_arg_type_name(PtnValue value) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_OBJECT:
            return value.as.object->class_name;
        case PTN_EXCEPTION:
            return value.as.exception->class_name;
        case PTN_CLOSURE:
            return "Closure";
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_INT:
        case PTN_FLOAT:
        case PTN_STRING:
        case PTN_ARRAY:
        case PTN_RESOURCE:
        case PTN_REFERENCE:
            return ptn_offset_container_type_name(value);
    }
    return ptn_offset_container_type_name(value);
}

static void ptn_internal_throw_string_arg_type_error(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value
) {
    value = ptn_value_deref(value);
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #%zu ($%s) must be of type string, %s given",
        function_name,
        position,
        argument_name,
        ptn_internal_string_arg_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
}

static PtnStringOperand ptn_internal_expect_string_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Passing null to parameter #%zu ($%s) of type string is deprecated",
            function_name,
            position,
            argument_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_deprecation(&runtime->diagnostics, message, line);
    } else if (value.type == PTN_OBJECT) {
        PtnStringOperand object_string;
        if (ptn_try_object_to_string_operand(runtime, value, line, &object_string)) {
            return object_string;
        }
        ptn_internal_throw_string_arg_type_error(runtime, function_name, position, argument_name, value);
        return ptn_string_operand_borrowed("");
    } else if (
        value.type == PTN_ARRAY ||
        value.type == PTN_CLOSURE ||
        value.type == PTN_EXCEPTION ||
        value.type == PTN_RESOURCE
    ) {
        ptn_internal_throw_string_arg_type_error(runtime, function_name, position, argument_name, value);
        return ptn_string_operand_borrowed("");
    }
    return ptn_value_to_string_operand_with_runtime(runtime, value, line);
}

static void ptn_highlight_append_escaped(PtnStringBuffer *buffer, const char *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        switch ((unsigned char)data[i]) {
            case '&':
                ptn_string_buffer_append(buffer, "&amp;");
                break;
            case '<':
                ptn_string_buffer_append(buffer, "&lt;");
                break;
            case '>':
                ptn_string_buffer_append(buffer, "&gt;");
                break;
            default:
                ptn_string_buffer_append_char(buffer, data[i]);
                break;
        }
    }
}

static PtnValue ptn_highlight_string_value(PtnStringOperand input) {
    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    ptn_string_buffer_append(&buffer, "<code><span style=\"color: #000000\">\n");
    ptn_highlight_append_escaped(&buffer, input.data, input.len);
    ptn_string_buffer_append(&buffer, "</span>\n</code>");
    return ptn_owned_string_len(buffer.data, buffer.len);
}

static PtnValue ptn_internal_highlight_string(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "highlight_string", 1, "string", args[0], line);
    int return_output = argc >= 2 && ptn_is_truthy(args[1]);
    PtnValue highlighted = ptn_highlight_string_value(input);
    ptn_string_operand_free(input);
    if (return_output) {
        return highlighted;
    }
    ptn_output_write(runtime, (const char *)highlighted.as.string.data, highlighted.as.string.len);
    ptn_value_destroy(&highlighted);
    return ptn_bool(1);
}

static void ptn_emit_highlight_file_open_warnings(
    PtnRuntime *runtime,
    const char *path,
    const char *reason,
    size_t line
) {
    if (!ptn_diagnostics_should_emit(&runtime->diagnostics, PTN_E_WARNING)) {
        return;
    }
    const char *source_path = runtime->source_path == NULL ? "ptn" : runtime->source_path;
    printf(
        "Warning: highlight_file(%s): Failed to open stream: %s in %s on line %zu\n\n",
        path,
        reason,
        source_path,
        line
    );
    printf(
        "Warning: highlight_file(): Failed opening '%s' for highlighting in %s on line %zu\n",
        path,
        source_path,
        line
    );
}

static PtnValue ptn_internal_highlight_file(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "highlight_file", 1, "filename", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "highlight_file(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    unsigned char *data = NULL;
    size_t data_len = 0;
    int read_result = ptn_read_file_bytes(path, &data, &data_len);
    if (read_result <= 0) {
        const char *reason = read_result == 0 ? strerror(errno) : "Failed to read stream";
        ptn_emit_highlight_file_open_warnings(runtime, path, reason, line);
        free(path);
        free(data);
        return ptn_bool(0);
    }

    PtnStringOperand input = ptn_string_operand_owned_len((char *)data, data_len);
    int return_output = argc >= 2 && ptn_is_truthy(args[1]);
    PtnValue highlighted = ptn_highlight_string_value(input);
    ptn_string_operand_free(input);
    free(path);
    if (return_output) {
        return highlighted;
    }
    ptn_output_write(runtime, (const char *)highlighted.as.string.data, highlighted.as.string.len);
    ptn_value_destroy(&highlighted);
    return ptn_bool(1);
}

static int ptn_get_meta_ascii_case_prefix(const char *data, size_t len, size_t offset, const char *literal) {
    size_t literal_len = strlen(literal);
    return offset <= len &&
           literal_len <= len - offset &&
           ptn_ascii_case_equal_n(data + offset, literal, literal_len);
}

static int ptn_get_meta_tag_boundary(const char *data, size_t len, size_t offset) {
    if (offset >= len) {
        return 1;
    }
    unsigned char byte = (unsigned char)data[offset];
    return isspace(byte) || byte == '/' || byte == '>';
}

static size_t ptn_get_meta_find_tag_end(const char *data, size_t len, size_t offset) {
    for (size_t i = offset; i < len; i++) {
        if (data[i] == '>') {
            return i;
        }
        if (data[i] == '<') {
            return SIZE_MAX;
        }
    }
    return SIZE_MAX;
}

static int ptn_get_meta_attr_name_byte(unsigned char byte) {
    return isalnum(byte) || byte == '_' || byte == '-' || byte == '.' || byte == ':';
}

static char *ptn_get_meta_read_attr_value(
    const char *data,
    size_t tag_end,
    size_t *offset,
    size_t *value_len_out
) {
    while (*offset < tag_end && isspace((unsigned char)data[*offset])) {
        (*offset)++;
    }
    if (*offset >= tag_end) {
        return NULL;
    }

    size_t value_start = *offset;
    size_t value_end = *offset;
    if (data[*offset] == '\'' || data[*offset] == '"') {
        char quote = data[(*offset)++];
        value_start = *offset;
        while (*offset < tag_end && data[*offset] != quote) {
            (*offset)++;
        }
        if (*offset >= tag_end) {
            return NULL;
        }
        value_end = *offset;
        (*offset)++;
    } else {
        while (*offset < tag_end && !isspace((unsigned char)data[*offset])) {
            (*offset)++;
        }
        value_end = *offset;
    }

    *value_len_out = value_end - value_start;
    return ptn_duplicate_string_len(data + value_start, *value_len_out);
}

static int ptn_get_meta_attr_name_equals(
    const char *data,
    size_t name_start,
    size_t name_len,
    const char *literal
) {
    size_t literal_len = strlen(literal);
    return name_len == literal_len && ptn_ascii_case_equal_n(data + name_start, literal, literal_len);
}

static void ptn_get_meta_parse_tag(
    const char *data,
    size_t attr_offset,
    size_t tag_end,
    char **name_out,
    size_t *name_len_out,
    char **content_out,
    size_t *content_len_out
) {
    size_t offset = attr_offset;
    while (offset < tag_end) {
        while (offset < tag_end && isspace((unsigned char)data[offset])) {
            offset++;
        }
        if (offset >= tag_end || data[offset] == '/') {
            break;
        }

        size_t attr_name_start = offset;
        while (offset < tag_end && ptn_get_meta_attr_name_byte((unsigned char)data[offset])) {
            offset++;
        }
        size_t attr_name_len = offset - attr_name_start;
        while (offset < tag_end && isspace((unsigned char)data[offset])) {
            offset++;
        }
        if (attr_name_len == 0 || offset >= tag_end || data[offset] != '=') {
            while (offset < tag_end && !isspace((unsigned char)data[offset])) {
                offset++;
            }
            continue;
        }
        offset++;

        size_t value_len = 0;
        char *value = ptn_get_meta_read_attr_value(data, tag_end, &offset, &value_len);
        if (value == NULL) {
            continue;
        }

        if (ptn_get_meta_attr_name_equals(data, attr_name_start, attr_name_len, "name")) {
            free(*name_out);
            *name_out = value;
            *name_len_out = value_len;
        } else if (ptn_get_meta_attr_name_equals(data, attr_name_start, attr_name_len, "content")) {
            free(*content_out);
            *content_out = value;
            *content_len_out = value_len;
        } else {
            free(value);
        }
    }
}

static char *ptn_get_meta_normalize_name(const char *name, size_t name_len, size_t *normalized_len_out) {
    char *normalized = malloc(name_len + 1);
    if (normalized == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < name_len; i++) {
        unsigned char byte = (unsigned char)name[i];
        normalized[i] = byte == '.' ? '_' : (char)tolower(byte);
    }
    normalized[name_len] = '\0';
    *normalized_len_out = name_len;
    return normalized;
}

static PtnValue ptn_get_meta_tags_from_bytes(const char *data, size_t len) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < len;) {
        if (data[i] != '<') {
            i++;
            continue;
        }
        if (ptn_get_meta_ascii_case_prefix(data, len, i, "</head")) {
            break;
        }
        if (!ptn_get_meta_ascii_case_prefix(data, len, i, "<meta") ||
            !ptn_get_meta_tag_boundary(data, len, i + 5)) {
            i++;
            continue;
        }

        size_t tag_end = ptn_get_meta_find_tag_end(data, len, i + 5);
        if (tag_end == SIZE_MAX) {
            i++;
            continue;
        }

        char *name = NULL;
        char *content = NULL;
        size_t name_len = 0;
        size_t content_len = 0;
        ptn_get_meta_parse_tag(data, i + 5, tag_end, &name, &name_len, &content, &content_len);
        if (name != NULL && content != NULL && name_len > 0) {
            size_t normalized_len = 0;
            char *normalized = ptn_get_meta_normalize_name(name, name_len, &normalized_len);
            ptn_array_set_entry(
                result.as.array,
                ptn_array_string_key_len(normalized, normalized_len),
                ptn_owned_string_len(content, content_len)
            );
            free(normalized);
            content = NULL;
        }
        free(name);
        free(content);
        i = tag_end + 1;
    }
    return result;
}

static PtnValue ptn_internal_get_meta_tags(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "get_meta_tags", 1, "filename", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "get_meta_tags(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    unsigned char *data = NULL;
    size_t data_len = 0;
    int read_result = ptn_read_file_bytes(path, &data, &data_len);
    if (read_result <= 0) {
        char detail[192];
        int needed = snprintf(
            detail,
            sizeof(detail),
            "%s: %s",
            read_result == 0 ? "Failed to open stream" : "Failed to read stream",
            strerror(errno)
        );
        if (needed < 0 || (size_t)needed >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_file_warning(runtime, "get_meta_tags", path, detail, line);
        free(path);
        free(data);
        return ptn_bool(0);
    }
    free(path);

    PtnValue result = ptn_get_meta_tags_from_bytes((const char *)data, data_len);
    free(data);
    return result;
}

static void ptn_php_strip_whitespace_append_pending(PtnStringBuffer *buffer, int *has_pending_space) {
    if (!*has_pending_space) {
        return;
    }
    if (buffer->len == 0 || buffer->data[buffer->len - 1] != ' ') {
        ptn_string_buffer_append_char(buffer, ' ');
    }
    *has_pending_space = 0;
}

static int ptn_php_strip_identifier_byte(unsigned char byte) {
    return isalnum(byte) || byte == '_';
}

static size_t ptn_php_strip_copy_quoted(
    PtnStringBuffer *buffer,
    const char *source,
    size_t len,
    size_t offset
) {
    char quote = source[offset++];
    ptn_string_buffer_append_char(buffer, quote);
    while (offset < len) {
        char byte = source[offset++];
        ptn_string_buffer_append_char(buffer, byte);
        if (byte == '\\' && offset < len) {
            ptn_string_buffer_append_char(buffer, source[offset++]);
            continue;
        }
        if (byte == quote) {
            break;
        }
    }
    return offset;
}

static size_t ptn_php_strip_copy_heredoc(
    PtnStringBuffer *buffer,
    const char *source,
    size_t len,
    size_t offset
) {
    size_t start = offset;
    offset += 3;
    while (offset < len && (source[offset] == ' ' || source[offset] == '\t')) {
        offset++;
    }
    char quote = '\0';
    if (offset < len && (source[offset] == '\'' || source[offset] == '"')) {
        quote = source[offset++];
    }

    size_t label_start = offset;
    while (offset < len && ptn_php_strip_identifier_byte((unsigned char)source[offset])) {
        offset++;
    }
    if (label_start == offset) {
        ptn_string_buffer_append_len(buffer, source + start, 3);
        return start + 3;
    }
    size_t label_len = offset - label_start;
    if (quote != '\0' && offset < len && source[offset] == quote) {
        offset++;
    }
    while (offset < len && source[offset] != '\n') {
        offset++;
    }
    if (offset < len) {
        offset++;
    }

    size_t scan = offset;
    while (scan < len) {
        size_t line_start = scan;
        size_t content_start = line_start;
        while (content_start < len && (source[content_start] == ' ' || source[content_start] == '\t')) {
            content_start++;
        }
        if (
            content_start + label_len <= len &&
            memcmp(source + content_start, source + label_start, label_len) == 0
        ) {
            size_t after_label = content_start + label_len;
            if (
                after_label >= len ||
                source[after_label] == ';' ||
                source[after_label] == '\r' ||
                source[after_label] == '\n'
            ) {
                scan = after_label;
                if (scan < len && source[scan] == ';') {
                    scan++;
                }
                if (scan < len && source[scan] == '\r') {
                    scan++;
                }
                if (scan < len && source[scan] == '\n') {
                    scan++;
                }
                ptn_string_buffer_append_len(buffer, source + start, scan - start);
                return scan;
            }
        }
        while (scan < len && source[scan] != '\n') {
            scan++;
        }
        if (scan < len) {
            scan++;
        }
    }

    ptn_string_buffer_append_len(buffer, source + start, len - start);
    return len;
}

static char *ptn_php_strip_whitespace_source(const char *source, size_t len, size_t *output_len_out) {
    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int in_php = 0;
    int has_pending_space = 0;

    for (size_t i = 0; i < len;) {
        if (!in_php) {
            if (
                i + 5 <= len &&
                source[i] == '<' &&
                source[i + 1] == '?' &&
                source[i + 2] == 'p' &&
                source[i + 3] == 'h' &&
                source[i + 4] == 'p'
            ) {
                ptn_string_buffer_append_len(&buffer, source + i, 5);
                i += 5;
                while (i < len && isspace((unsigned char)source[i])) {
                    ptn_string_buffer_append_char(&buffer, source[i++]);
                }
                in_php = 1;
                has_pending_space = 0;
                continue;
            }
            if (i + 2 <= len && source[i] == '<' && source[i + 1] == '?') {
                ptn_string_buffer_append_len(&buffer, source + i, 2);
                i += 2;
                in_php = 1;
                has_pending_space = 0;
                continue;
            }
            ptn_string_buffer_append_char(&buffer, source[i++]);
            continue;
        }

        unsigned char byte = (unsigned char)source[i];
        if (isspace(byte)) {
            has_pending_space = 1;
            i++;
            continue;
        }
        if (i + 2 <= len && source[i] == '?' && source[i + 1] == '>') {
            if (has_pending_space) {
                ptn_string_buffer_append_char(&buffer, ' ');
                has_pending_space = 0;
            }
            ptn_string_buffer_append_len(&buffer, source + i, 2);
            i += 2;
            in_php = 0;
            continue;
        }
        if (i + 2 <= len && source[i] == '/' && source[i + 1] == '/') {
            has_pending_space = 1;
            i += 2;
            while (i < len && source[i] != '\n') {
                i++;
            }
            continue;
        }
        if (source[i] == '#') {
            has_pending_space = 1;
            i++;
            while (i < len && source[i] != '\n') {
                i++;
            }
            continue;
        }
        if (i + 2 <= len && source[i] == '/' && source[i + 1] == '*') {
            has_pending_space = 1;
            i += 2;
            while (i + 1 < len && !(source[i] == '*' && source[i + 1] == '/')) {
                i++;
            }
            if (i + 1 < len) {
                i += 2;
            }
            continue;
        }

        ptn_php_strip_whitespace_append_pending(&buffer, &has_pending_space);
        if (source[i] == '\'' || source[i] == '"') {
            i = ptn_php_strip_copy_quoted(&buffer, source, len, i);
            continue;
        }
        if (i + 3 <= len && source[i] == '<' && source[i + 1] == '<' && source[i + 2] == '<') {
            i = ptn_php_strip_copy_heredoc(&buffer, source, len, i);
            continue;
        }
        ptn_string_buffer_append_char(&buffer, source[i++]);
    }

    *output_len_out = buffer.len;
    if (buffer.data == NULL) {
        return ptn_duplicate_string("");
    }
    return buffer.data;
}

static void ptn_emit_php_strip_whitespace_open_warning(
    PtnRuntime *runtime,
    const char *path,
    const char *reason,
    size_t line
) {
    if (!ptn_diagnostics_should_emit(&runtime->diagnostics, PTN_E_WARNING)) {
        return;
    }
    const char *source_path = runtime->source_path == NULL ? "ptn" : runtime->source_path;
    printf(
        "Warning: php_strip_whitespace(%s): Failed to open stream: %s in %s on line %zu\n",
        path,
        reason,
        source_path,
        line
    );
}

static PtnValue ptn_internal_php_strip_whitespace(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "php_strip_whitespace", 1, "filename", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "php_strip_whitespace(): Filename contains null byte", line);
        return ptn_string("");
    }

    unsigned char *data = NULL;
    size_t data_len = 0;
    int read_result = ptn_read_file_bytes(path, &data, &data_len);
    if (read_result <= 0) {
        const char *reason = read_result == 0 ? strerror(errno) : "Failed to read stream";
        ptn_emit_php_strip_whitespace_open_warning(runtime, path, reason, line);
        free(path);
        free(data);
        return ptn_string("");
    }
    free(path);

    size_t output_len = 0;
    char *output = ptn_php_strip_whitespace_source((const char *)data, data_len, &output_len);
    free(data);
    return ptn_owned_string_len(output, output_len);
}

static PtnValue ptn_internal_dirname(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand path = ptn_internal_expect_string_arg(runtime, "dirname", 1, "path", args[0], line);
    int64_t levels = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "dirname", 2, "levels", args[1], line)
        : 1;
    if (levels < 1) {
        ptn_string_operand_free(path);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "dirname(): Argument #2 ($levels) must be greater than or equal to 1"
        );
        return ptn_null();
    }

    size_t dirname_len = 0;
    char *dirname = ptn_dirname_string_levels(path.data, path.len, levels, &dirname_len);
    ptn_string_operand_free(path);
    return ptn_owned_string_len(dirname, dirname_len);
}

static PtnValue ptn_internal_gettype(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)line;
    return ptn_gettype_value(args[0]);
}

static PtnValue ptn_internal_settype(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    if (args[0].type != PTN_REFERENCE) {
        if (runtime->warn_by_ref_argument_mismatch) {
            ptn_emit_by_reference_argument_warning(runtime, "settype", 1, "var", line);
            return ptn_bool(0);
        }
        ptn_throw_by_reference_argument_error(runtime, "settype", 1, "var", line);
        return ptn_null();
    }

    PtnStringOperand type = ptn_value_to_string_operand(args[1]);
    PtnValue current = ptn_value_deref(args[0].as.reference->value);
    PtnValue converted;
    int valid = 1;

    if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "null")) {
        converted = ptn_null();
    } else if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "integer") ||
        ptn_ascii_case_equal_span_to_string(type.data, type.len, "int")) {
        converted = ptn_int(ptn_value_to_integer(current));
    } else if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "double") ||
        ptn_ascii_case_equal_span_to_string(type.data, type.len, "float")) {
        converted = ptn_float(ptn_value_to_double(current));
    } else if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "string")) {
        PtnStringOperand string = ptn_value_to_string_operand_with_runtime(runtime, current, line);
        converted = ptn_owned_string_len(
            ptn_duplicate_string_len(string.data, string.len),
            string.len
        );
        ptn_string_operand_free(string);
    } else if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "boolean") ||
        ptn_ascii_case_equal_span_to_string(type.data, type.len, "bool")) {
        converted = ptn_bool(ptn_is_truthy(current));
    } else if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "array")) {
        converted = ptn_cast_array(current);
    } else if (ptn_ascii_case_equal_span_to_string(type.data, type.len, "object")) {
        converted = ptn_cast_object(runtime, current);
    } else {
        valid = 0;
        converted = ptn_null();
    }

    ptn_string_operand_free(type);
    if (!valid) {
        ptn_throw_exception(runtime, "ValueError", "settype(): Argument #2 ($type) must be a valid type");
        return ptn_null();
    }

    ptn_value_destroy(&args[0].as.reference->value);
    args[0].as.reference->value = converted;
    return ptn_bool(1);
}

