static int ptn_string_operand_ascii_case_equal(PtnStringOperand value, const char *literal) {
    size_t literal_len = strlen(literal);
    if (value.len != literal_len) {
        return 0;
    }
    for (size_t i = 0; i < literal_len; i++) {
        if (tolower((unsigned char)value.data[i]) != tolower((unsigned char)literal[i])) {
            return 0;
        }
    }
    return 1;
}

static PtnRuntime *ptn_runtime_config_root(PtnRuntime *runtime) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    return root == NULL ? runtime : root;
}

static PtnValue ptn_ini_int_string(int value) {
    char buffer[32];
    int written = snprintf(buffer, sizeof(buffer), "%d", value);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_owned_string(ptn_duplicate_string(buffer));
}

static PtnValue ptn_ini_size_string(size_t value) {
    char buffer[32];
    int written = snprintf(buffer, sizeof(buffer), "%zu", value);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_owned_string(ptn_duplicate_string(buffer));
}

static const char *ptn_runtime_memory_limit(PtnRuntime *runtime) {
    PtnRuntime *root = ptn_runtime_config_root(runtime);
    if (root == NULL || root->memory_limit == NULL) {
        return "128M";
    }
    return root->memory_limit;
}

