static int ptn_runtime_set_zend_assertions(PtnRuntime *runtime, int64_t requested, size_t line) {
    PtnRuntime *root = ptn_runtime_config_root(runtime);
    if (requested < 0) {
        ptn_emit_runtime_warning(
            runtime,
            "zend.assertions may be completely enabled or disabled only in php.ini",
            line
        );
        return 0;
    }
    if (root->initial_zend_assertions < 0) {
        ptn_emit_runtime_warning(
            runtime,
            "zend.assertions may be completely enabled or disabled only in php.ini",
            line
        );
        return 0;
    }
    root->zend_assertions = requested == 0 ? 0 : 1;
    return 1;
}

static void ptn_runtime_set_memory_limit(PtnRuntime *runtime, const char *memory_limit) {
    PtnRuntime *root = ptn_runtime_config_root(runtime);
    char *copy = ptn_duplicate_string(memory_limit);
    free(root->memory_limit);
    root->memory_limit = copy;
}

static void ptn_runtime_apply_memory_limit(PtnRuntime *runtime, const char *requested, size_t line) {
    int64_t max_value = ptn_parse_ini_quantity_operand(
        runtime,
        ptn_string_operand_borrowed(ptn_runtime_max_memory_limit(runtime)),
        line
    );
    if (max_value < 0) {
        ptn_runtime_set_memory_limit(runtime, requested);
        return;
    }

    int64_t requested_value = ptn_parse_ini_quantity_operand(
        runtime,
        ptn_string_operand_borrowed(requested),
        line
    );
    if (requested_value > max_value) {
        char message[192];
        snprintf(
            message,
            sizeof(message),
            "Failed to set memory_limit to %lld bytes. Setting to max_memory_limit instead (currently: %lld bytes)",
            (long long)requested_value,
            (long long)max_value
        );
        ptn_emit_sourced_ini_warning(runtime, message, line);
        ptn_runtime_set_memory_limit(runtime, ptn_runtime_max_memory_limit(runtime));
    } else if (requested_value < 0) {
        ptn_runtime_set_memory_limit(runtime, ptn_runtime_max_memory_limit(runtime));
    } else {
        ptn_runtime_set_memory_limit(runtime, requested);
    }
}

static int ptn_is_modeled_extension_operand(PtnStringOperand extension) {
    return ptn_string_operand_ascii_case_equal(extension, "Core") ||
        ptn_string_operand_ascii_case_equal(extension, "ctype") ||
        ptn_string_operand_ascii_case_equal(extension, "date") ||
        ptn_string_operand_ascii_case_equal(extension, "json") ||
        ptn_string_operand_ascii_case_equal(extension, "pcre") ||
        ptn_string_operand_ascii_case_equal(extension, "Reflection") ||
        ptn_string_operand_ascii_case_equal(extension, "standard");
}

static int ptn_ini_value(PtnRuntime *runtime, PtnStringOperand option, PtnValue *out) {
    if (ptn_string_operand_ascii_case_equal(option, "date.timezone")) {
        *out = ptn_string("UTC");
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "assert.exception")) {
        *out = ptn_ini_int_string(ptn_runtime_assert_exception(runtime));
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "display_errors")) {
        const char *configured = getenv("PTN_PHP_DISPLAY_ERRORS");
        *out = ptn_string(configured == NULL ? "1" : configured);
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "extension_dir")) {
        *out = ptn_string(PTN_PHP_EXTENSION_DIR);
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "include_path")) {
        *out = ptn_string(".");
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "open_basedir")) {
        PtnRuntime *root = ptn_runtime_root(runtime);
        *out = ptn_owned_string(ptn_duplicate_string(root == NULL || root->open_basedir == NULL ? "" : root->open_basedir));
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "max_memory_limit")) {
        *out = ptn_owned_string(ptn_duplicate_string(ptn_runtime_max_memory_limit(runtime)));
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "memory_limit")) {
        *out = ptn_owned_string(ptn_duplicate_string(ptn_runtime_memory_limit(runtime)));
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "pcre.backtrack_limit")) {
        *out = ptn_string("1000000");
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "precision")) {
        *out = ptn_string("14");
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.assertions")) {
        *out = ptn_ini_int_string(ptn_runtime_current_zend_assertions(runtime));
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.exception_ignore_args")) {
        *out = ptn_ini_int_string(ptn_runtime_exception_ignore_args(runtime));
        return 1;
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.exception_string_param_max_len")) {
        *out = ptn_ini_size_string(ptn_runtime_exception_string_param_max_len(runtime));
        return 1;
    }
    return 0;
}

static const char *ptn_runtime_current_include_path(PtnRuntime *runtime) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL || root->include_path == NULL) {
        return ".";
    }
    return root->include_path;
}

static void ptn_runtime_set_include_path(PtnRuntime *runtime, const char *path) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        return;
    }
    char *copy = ptn_duplicate_string(path);
    free(root->include_path);
    root->include_path = copy;
}

static const char *ptn_runtime_current_open_basedir(PtnRuntime *runtime) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL || root->open_basedir == NULL) {
        return "";
    }
    return root->open_basedir;
}

static void ptn_runtime_set_open_basedir(PtnRuntime *runtime, const char *path) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        return;
    }
    char *copy = ptn_duplicate_string(path);
    free(root->open_basedir);
    root->open_basedir = copy;
}

static int ptn_environment_put_owned(char *assignment) {
#if defined(_WIN32)
    int result = _putenv(assignment);
    free(assignment);
    return result == 0;
#else
    char *equals = strchr(assignment, '=');
    if (equals == NULL || equals == assignment) {
        free(assignment);
        return 0;
    }
    *equals = '\0';
    int result = setenv(assignment, equals + 1, 1);
    free(assignment);
    return result == 0;
#endif
}

static int ptn_environment_unset(const char *name) {
#if defined(_WIN32)
    size_t name_len = strlen(name);
    if (name_len > SIZE_MAX - 2) {
        ptn_abort_out_of_memory();
    }
    char *assignment = malloc(name_len + 2);
    if (assignment == NULL) {
        ptn_abort_out_of_memory();
    }
    memcpy(assignment, name, name_len);
    assignment[name_len] = '=';
    assignment[name_len + 1] = '\0';
    int result = _putenv(assignment);
    free(assignment);
    return result == 0;
#else
    return unsetenv(name) == 0;
#endif
}

static PtnValue ptn_internal_get_include_path(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    return ptn_owned_string(ptn_duplicate_string(ptn_runtime_current_include_path(runtime)));
}

static PtnValue ptn_internal_ini_parse_quantity(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "ini_parse_quantity", 1, "shorthand", args[0], line);
    int64_t quantity = ptn_parse_ini_quantity_operand(runtime, input, line);
    ptn_string_operand_free(input);
    return ptn_int(quantity);
}

static PtnValue ptn_internal_set_include_path(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path = ptn_internal_expect_string_arg(runtime, "set_include_path", 1, "include_path", args[0], line);
    if (path.len == 0) {
        ptn_string_operand_free(path);
        return ptn_bool(0);
    }
    char *previous = ptn_duplicate_string(ptn_runtime_current_include_path(runtime));
    char *next = ptn_duplicate_string_len(path.data, path.len);
    ptn_runtime_set_include_path(runtime, next);
    free(next);
    ptn_string_operand_free(path);
    return ptn_owned_string(previous);
}

static PtnValue ptn_internal_ini_restore(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand option = ptn_internal_expect_string_arg(runtime, "ini_restore", 1, "option", args[0], line);
    if (ptn_string_operand_ascii_case_equal(option, "include_path")) {
        ptn_runtime_set_include_path(runtime, ".");
        ptn_string_operand_free(option);
        return ptn_null();
    }
    if (ptn_string_operand_ascii_case_equal(option, "open_basedir")) {
        ptn_runtime_set_open_basedir(runtime, "");
        ptn_string_operand_free(option);
        return ptn_null();
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.assertions")) {
        PtnRuntime *root = ptn_runtime_config_root(runtime);
        root->zend_assertions = root->initial_zend_assertions;
        ptn_string_operand_free(option);
        return ptn_null();
    }
    if (ptn_string_operand_ascii_case_equal(option, "assert.exception")) {
        ptn_runtime_set_assert_exception(runtime, 1);
        ptn_string_operand_free(option);
        return ptn_null();
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.exception_ignore_args")) {
        ptn_runtime_set_exception_ignore_args(runtime, 0);
        ptn_string_operand_free(option);
        return ptn_null();
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.exception_string_param_max_len")) {
        ptn_runtime_set_exception_string_param_max_len(runtime, 15);
        ptn_string_operand_free(option);
        return ptn_null();
    }
    PtnValue value;
    int known = ptn_ini_value(runtime, option, &value);
    if (known) {
        ptn_value_destroy(&value);
    }
    ptn_string_operand_free(option);
    return known ? ptn_null() : ptn_bool(0);
}

static PtnValue ptn_internal_ini_set(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand option = ptn_internal_expect_string_arg(runtime, "ini_set", 1, "option", args[0], line);
    if (ptn_string_operand_ascii_case_equal(option, "include_path")) {
        PtnValue previous = ptn_owned_string(ptn_duplicate_string(ptn_runtime_current_include_path(runtime)));
        PtnStringOperand value = ptn_value_to_string_operand(args[1]);
        char *next = ptn_duplicate_string_len(value.data, value.len);
        ptn_runtime_set_include_path(runtime, next);
        free(next);
        ptn_string_operand_free(value);
        ptn_string_operand_free(option);
        return previous;
    }
    if (ptn_string_operand_ascii_case_equal(option, "open_basedir")) {
        PtnValue previous = ptn_owned_string(ptn_duplicate_string(ptn_runtime_current_open_basedir(runtime)));
        PtnStringOperand value = ptn_value_to_string_operand(args[1]);
        char *next = ptn_duplicate_string_len(value.data, value.len);
        ptn_runtime_set_open_basedir(runtime, next);
        free(next);
        ptn_string_operand_free(value);
        ptn_string_operand_free(option);
        return previous;
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.assertions")) {
        PtnValue previous = ptn_ini_int_string(ptn_runtime_current_zend_assertions(runtime));
        ptn_runtime_set_zend_assertions(runtime, ptn_value_to_integer(args[1]), line);
        ptn_string_operand_free(option);
        return previous;
    }
    if (ptn_string_operand_ascii_case_equal(option, "assert.exception")) {
        PtnValue previous = ptn_ini_int_string(ptn_runtime_assert_exception(runtime));
        ptn_runtime_set_assert_exception(runtime, ptn_is_truthy(args[1]));
        ptn_string_operand_free(option);
        return previous;
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.exception_ignore_args")) {
        PtnValue previous = ptn_ini_int_string(ptn_runtime_exception_ignore_args(runtime));
        ptn_runtime_set_exception_ignore_args(runtime, ptn_is_truthy(args[1]));
        ptn_string_operand_free(option);
        return previous;
    }
    if (ptn_string_operand_ascii_case_equal(option, "zend.exception_string_param_max_len")) {
        int64_t requested = ptn_value_to_integer(args[1]);
        if (requested < 0 || requested > 1000000) {
            ptn_string_operand_free(option);
            return ptn_bool(0);
        }
        PtnValue previous =
            ptn_ini_size_string(ptn_runtime_exception_string_param_max_len(runtime));
        ptn_runtime_set_exception_string_param_max_len(runtime, (size_t)requested);
        ptn_string_operand_free(option);
        return previous;
    }
    if (ptn_string_operand_ascii_case_equal(option, "memory_limit")) {
        PtnValue previous = ptn_owned_string(ptn_duplicate_string(ptn_runtime_memory_limit(runtime)));
        PtnStringOperand value = ptn_value_to_string_operand(args[1]);
        char *requested = ptn_duplicate_string_len(value.data, value.len);
        ptn_runtime_apply_memory_limit(runtime, requested, line);
        free(requested);
        ptn_string_operand_free(value);
        ptn_string_operand_free(option);
        return previous;
    }
    PtnValue known_value;
    int known = ptn_ini_value(runtime, option, &known_value);
    if (known) {
        ptn_value_destroy(&known_value);
    }
    ptn_string_operand_free(option);
    return ptn_bool(0);
}

static PtnValue ptn_internal_getenv(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (argc == 0) {
        (void)runtime;
        (void)args;
        (void)line;
        return ptn_environment_snapshot();
    }

    PtnStringOperand name = ptn_internal_expect_string_arg(runtime, "getenv", 1, "name", args[0], line);
    if (memchr(name.data, '\0', name.len) != NULL) {
        ptn_string_operand_free(name);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "getenv(): Argument #1 ($name) must not contain any null bytes"
        );
        return ptn_null();
    }
    char *key = ptn_duplicate_string_len(name.data, name.len);
    ptn_string_operand_free(name);
    const char *value = getenv(key);
    free(key);
    if (value == NULL) {
        return ptn_bool(0);
    }
    return ptn_owned_string(ptn_duplicate_string(value));
}

static PtnValue ptn_internal_putenv(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand assignment = ptn_internal_expect_string_arg(runtime, "putenv", 1, "assignment", args[0], line);
    if (memchr(assignment.data, '\0', assignment.len) != NULL) {
        ptn_string_operand_free(assignment);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "putenv(): Argument #1 ($assignment) must not contain any null bytes"
        );
        return ptn_null();
    }
    if (assignment.len == 0 || assignment.data[0] == '=') {
        ptn_string_operand_free(assignment);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "putenv(): Argument #1 ($assignment) must have a valid syntax"
        );
        return ptn_null();
    }

    const char *equals = memchr(assignment.data, '=', assignment.len);
    int ok;
    if (equals == NULL) {
        char *name = ptn_duplicate_string_len(assignment.data, assignment.len);
        ok = ptn_environment_unset(name);
        free(name);
    } else {
        char *owned_assignment = ptn_duplicate_string_len(assignment.data, assignment.len);
        ok = ptn_environment_put_owned(owned_assignment);
    }
    ptn_string_operand_free(assignment);
    return ptn_bool(ok);
}

