static const PtnInternalFunction *ptn_find_internal_function(const char *name) {
    size_t count = 0;
    const PtnInternalFunction *functions = ptn_internal_functions(&count);
    for (size_t i = 0; i < count; i++) {
        if (ptn_ascii_case_equal(name, functions[i].name)) {
            return &functions[i];
        }
    }
    return NULL;
}

static PtnValue ptn_internal_function_names(void) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    size_t count = 0;
    const PtnInternalFunction *functions = ptn_internal_functions(&count);
    int64_t next_index = 0;
    for (size_t i = 0; i < count; i++) {
        const char *name = functions[i].name;
        if (strncmp(name, "_ptn_", 5) == 0 || strstr(name, "::") != NULL) {
            continue;
        }
        ptn_array_set_entry(result.as.array, ptn_array_int_key(next_index++), ptn_string(name));
    }
    return result;
}

static PtnValue ptn_internal_get_defined_functions(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, ptn_array_string_key("internal"), ptn_internal_function_names());
    ptn_array_set_entry(result.as.array, ptn_array_string_key("user"), ptn_user_function_names(runtime));
    return result;
}

static PtnFunctionMetadata ptn_internal_function_metadata(const PtnInternalFunction *function) {
    if (function == NULL) {
        return ptn_function_metadata_not_found();
    }
    static const PtnParameterMetadata PTN_INTERNAL_EXIT_PARAMETERS[] = {
        { "status", NULL, NULL, 0, 0, 0, 0, 1 },
    };
    if (ptn_ascii_case_equal(function->name, "exit") || ptn_ascii_case_equal(function->name, "die")) {
        return ptn_function_metadata_found(
            "exit",
            1,
            sizeof(PTN_INTERNAL_EXIT_PARAMETERS) / sizeof(PTN_INTERNAL_EXIT_PARAMETERS[0]),
            0,
            0,
            PTN_INTERNAL_EXIT_PARAMETERS,
            NULL,
            NULL,
            0,
            0
        );
    }
    if (ptn_ascii_case_equal(function->name, "htmlspecialchars")) {
        return ptn_function_metadata_found(
            function->name,
            1,
            sizeof(PTN_INTERNAL_HTMLSPECIALCHARS_PARAMETERS) / sizeof(PTN_INTERNAL_HTMLSPECIALCHARS_PARAMETERS[0]),
            1,
            0,
            PTN_INTERNAL_HTMLSPECIALCHARS_PARAMETERS,
            "string",
            "string",
            0,
            1
        );
    }
    if (ptn_ascii_case_equal(function->name, "get_html_translation_table")) {
        return ptn_function_metadata_found(
            function->name,
            1,
            sizeof(PTN_INTERNAL_GET_HTML_TRANSLATION_TABLE_PARAMETERS) /
                sizeof(PTN_INTERNAL_GET_HTML_TRANSLATION_TABLE_PARAMETERS[0]),
            0,
            0,
            PTN_INTERNAL_GET_HTML_TRANSLATION_TABLE_PARAMETERS,
            "array",
            "array",
            0,
            1
        );
    }
    int is_variadic = function->max_args == PTN_VARIADIC_ARGS;
    size_t parameter_count = is_variadic ? function->min_args + 1 : function->max_args;
    return ptn_function_metadata_found(
        function->name,
        1,
        parameter_count,
        function->min_args,
        is_variadic,
        NULL,
        NULL,
        NULL,
        0,
        0
    );
}

static PtnFunctionMetadata ptn_find_function_metadata(const char *name) {
    PtnFunctionMetadata metadata = ptn_user_function_metadata(name);
    if (metadata.found) {
        return metadata;
    }
    return ptn_internal_function_metadata(ptn_find_internal_function(name));
}

static PtnValue ptn_internal_closure_from_callable(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnValue callable = ptn_value_deref(args[0]);
    if (callable.type == PTN_CLOSURE) {
        return ptn_value_clone(callable);
    }
    if (!ptn_callable_is_valid(runtime, callable, 0)) {
        char *message = ptn_invalid_callback_message(
            "Closure::fromCallable",
            1,
            "callback",
            callable,
            0
        );
        ptn_throw_exception_owned_message(runtime, "TypeError", message);
        return ptn_null();
    }
    char *name = ptn_callable_output_name(callable);
    PtnFunctionMetadata metadata = ptn_find_function_metadata(name);
    free(name);
    return ptn_closure_wrap_callable(runtime, callable, metadata);
}

static PtnValue ptn_internal_closure_bind(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_closure_bind_to(
        runtime,
        args[0],
        args[1],
        argc >= 3,
        argc >= 3 ? args[2] : ptn_null(),
        "Closure::bind",
        2,
        3,
        line
    );
}

